def _c(name, value, thr, passed, note="", **extra):
    d = dict(name=name, value=value, threshold=thr, passed=bool(passed), note=note)
    d.update(extra)          # ★ 可带 dp=（DP 标定值，验收协议 v2 的 DP≥5 口径）、dp_source= 等
    return d


def _r2(X, Y):
    F = np.column_stack([X, np.ones(len(X))])
    w = np.linalg.lstsq(F, Y, rcond=None)[0]
    p = F @ w
    return float(1 - ((Y - p) ** 2).sum() / ((Y - Y.mean(0)) ** 2).sum())


def _cond_mi(x, y, z, nb=6):
    d = lambda v: np.digitize(v, np.quantile(v, np.linspace(0, 1, nb + 1)[1:-1]))
    H1 = lambda a: -(lambda p: (p * np.log2(p)).sum())(np.bincount(a, minlength=nb)[np.bincount(a, minlength=nb) > 0] / len(a))
    def H2(a, b):
        i = a * nb + b; c = np.bincount(i, minlength=nb * nb).astype(float); p = c / c.sum(); p = p[p > 0]
        return -(p * np.log2(p)).sum()
    def H3(a, b, cc):
        i = (a * nb + b) * nb + cc; c = np.bincount(i, minlength=nb ** 3).astype(float); p = c / c.sum(); p = p[p > 0]
        return -(p * np.log2(p)).sum()
    return float(H2(d(y), d(z)) + H2(d(x), d(z)) - H1(d(z)) - H3(d(y), d(x), d(z)))


def _lz76(x):
    thr = float(np.median(x)); s = "".join("1" if v > thr else "0" for v in x)
    n = len(s); i = k = l = 1; c = 1
    while i + k <= n:
        if s[i:i + k] == s[i + l:i + l + k]:
            k += 1
        else:
            l += k; k = 1; c += 1
            if i + l > n: break
        if i + k > n:
            i += 1; l = k = 1
            if i + l > n: break
    return c * np.log2(max(n, 2)) / max(n, 1)


def tau_est(x, maxlag: int = 300) -> float:
    """★ **已废弃（有偏）**：积分自相关时间 τ = 1 + 2·Σρ_k，累加至第一个 ρ_k ≤ 0（或 maxlag）。

    ⚠ **已知有偏：τ≳300 时系统性低估 20–77%**（合成 AR(1) 标定，见 meeting6/T3_估计器标定.txt /
    T4_标定校正.txt）。根因 = `maxlag` 截断 + 首个 ρ_k ≤ 0 提前终止 + 有限样本截断偏置。
    **仅用于复现历史数值，不得用于新判定**；新判定请用 `tau_fit`（AR(1) 标定校正）。
    口径**沿既有探针**（meeting3/T1_probe_tau_forensics.py、M3/M4、meeting5/N0），未改：
    去均值；ρ_k = Σ(x[:-k]·x[k:])/Σ(x²)·(n/(n−k))。
    （历史：N1 于 2026-09-25 预注册时曾用此函数；2026-09-26 换为 tau_fit，见 _CHANGELOG。）
    """
    x = np.asarray(x, float)
    x = x - x.mean()
    v = float((x * x).sum())
    if v <= 0:
        return 0.0
    s = 0.0
    for k in range(1, maxlag):
        rho = float((x[:-k] * x[k:]).sum()) / v * (len(x) / max(len(x) - k, 1))
        if rho <= 0:
            break
        s += rho
    return 1.0 + 2.0 * s


tau_est_legacy = tau_est          # ★ 显式别名：历史数值复现用（有偏，见上）


def tau_fit(x, lag: int = 1) -> float:
    """AR(1)/OU **标定校正**的积分自相关时间：τ̂ = (1+â)/(1−â)，â = 条件 MLE（=OLS）。

    â = Σ(x_t−x̄)(x_{t−1}−x̄) / Σ(x_{t−1}−x̄)²   （去均值后的 lag-1 OLS，即 AR(1)+截距的条件 MLE）

    与旧 `tau_est` 的差别（全部在**估计器内部**，不含任何阈值）：
      ① **不做 maxlag 截断**（旧尺在 maxlag=300 时对 τ=441 截在 300 个 lag，是最大的低估源）；
      ② **不在 ρ_k ≤ 0 处提前终止**（旧尺一旦某个 ρ̂_k 因噪声穿零就截断整个和）；
      ③ 改用 AR(1) 参数化（只依赖 ρ̂₁，但**不**做会过校正的经验公式 —— 见下）。
    ★ 已实测（meeting6/T4_估计器族探查.txt，9 实现 × 7 档真值）：在本标定下
      『`â = ρ̂₁ + (1+3·ρ̂₁)/n`』这类 Kendall 一阶校正是**有害的**（去均值 OLS 已基本抵消该偏置；
      再加校正会把 â 推过 1 ⇒ τ 炸到 1e6）。故本函数**不加**该校正，直接取 OLS。
    ★ 标定（合成 AR(1)，真值 τ_int=(1+a)/(1−a)；T=8000 ⇒ n=7600）：
      |偏差| = 1.1%/0.3%/2.1%/2.7%/3.3%/−5.1%/−10.0%（τ_true = 100/300/441/500/1000/2000/2500）；
      相对 sd ≈ CRLB = sqrt(τ/n)（11.5% → 33.6%）。T=1500（n=1100）下同法偏差 −19%…−73%、sd 53–99%
      ⇒ **必须换到长窗口**（N1 已预注册 T=8000）。
    ★ 测量不确定度（CRLB）：相对 sd ≈ sqrt(τ/n)。τ=2500、n=7600 时约 **±34%**
      ⇒ **τ ≳ 2000 时"两个值谁更大"在 2× 以内不可分辨**；此类比较须同时报不确定度。
    ★ 本函数**只是尺子**：比较式与阈值由调用方（verify_N1）给出；换尺不改变任何判据逻辑。
    ⚠ **适用性边界（2026-09-26 实测，重要）**：AR(1) 尺只对**近似平稳**的序列有效。
      引擎真序列实测（T=8000，meeting6/T4_ρ1诊断.txt）：ρ̂₁(h_slow) = 0.9973 – **1.000015**（含 >1 的
      非平稳值）、ρ̂₁(h) 同量级 ⇒ **h/h_slow 是近单位根（非平稳）过程**：其"τ"≈ n/c 随窗口线性增长，
      τ_fit 会撞到 1e−6 的截断（返回 1999999）——该值是**截断伪影、不是时间常数**；
      而 ρ̂₁(m1) = −0.9998…−0.031、ρ̂₁(self.m) 混合 ⇒ m1 近白/反相 ⇒ τ_fit ≈ 0。
      ⇒ 对本引擎的 h/h_slow/m1/self.m，**"τ 大小比较"不是一个可辨识的量**（缺平稳性前提）。
      调用方（verify_N1）须同时报不确定度与截断标记，不得把这类数值当"真值"。
    ⛔ **守卫（2026-09-26b 预注册，见 _CHANGELOG）**：当 ρ̂₁ **不可辨识**时本函数返回 `np.nan`，
      **绝不返回截断值**。可辨识判据 = `ρ̂₁ + 2·SE(ρ̂₁) < 1`（SE = sqrt((1−ρ̂₁²)/n)；
      即 AR(1) 的 a=1 之 95% 单侧不被拒绝 ⇒ 判为不可辨识）**且** `ρ̂₁ > −1`。
      需要 ρ̂₁/SE/标记时请用 `tau_fit_detail`。
    """
    return tau_fit_detail(x, lag=lag)[0]


def tau_fit_detail(x, lag: int = 1):
    """`tau_fit` 的明细版：返回 `(tau, rho1, se, identifiable)`。

    · tau          ：可辨识时为 (1+â)/(1−â)；**不可辨识时为 `np.nan`**（不返回截断值/任何有限数）
    · rho1         ：去均值 lag-1 自相关 ρ̂₁（原始观测，便于审计）
    · se           ：SE(ρ̂₁) ≈ sqrt((1−ρ̂₁²)/n)（AR(1) 近似；不可辨识时仍原样给出）
    · identifiable ：`rho1 + 2*se < 1 and rho1 > -1`（且有限）
    """
    x = np.asarray(x, float).ravel()
    n = len(x)
    k = int(max(1, lag))
    if n - k < 60:
        return float("nan"), float("nan"), float("nan"), False
    x = x - x.mean()
    den = float((x[:-k] * x[:-k]).sum())
    if den <= 0:
        return float("nan"), float("nan"), float("nan"), False
    rho1 = float((x[:-k] * x[k:]).sum()) / den
    se = float(np.sqrt(max(1.0 - min(rho1 * rho1, 1.0), 0.0) / max(n, 1)))
    ident = bool(np.isfinite(rho1) and np.isfinite(se) and rho1 > -1.0 and (rho1 + 2.0 * se) < 1.0)
    if not ident:
        return float("nan"), rho1, se, False
    a = float(np.clip(rho1, -0.999999, 0.999999))
    return float((1.0 + a) / (1.0 - a)), rho1, se, True


