     "(a) 无守卫 gated@z 在 G1 上灾难性假阳（G1@5% 0.100–0.325）——周期散洞被误判为跳变；"
     "(b) 加 mw8192 守卫后 G1/G2 复原为 raw（G1@5% 0.950/0.925、G2 0.900/0.900），但 G3 仅 0.750(判据集)/0.825(留出集)，"
