     "判据集 synth=0.9125{A1.0,B1.0,C1 0.85,C2 1.0,C3 0.625,D 1.0}、分型四门{G1@5% 0.925,G1@20% 0.925,G2 0.925,G3 0.975} ⇒ gate=True；"
     "留出集 synth=0.9167{A1.0,B1.0,C1 0.925,C2 1.0,C3 0.600,D 0.975}、{1.000,0.975,0.950,0.925} ⇒ gate=True。"
     "⇒ 分型候选在 T=131072(B40/B80) 与 T=262144(B40) 共三组独立测量下均过线；唯一临界项为 synth 边际（0.9125/0.9167 vs 0.90）。"
     "根因定位（C3 混淆矩阵，直接测量）：C3 错分全部落入 C2、与 r2 无关——base 与 r2 计数逐项相同"
     "（T=131072：C3→C2 2/40 判据集、3/40 留出集；T=262144：15/40、16/40）⇒ r2 在 C3 上零假阳；"
