     "B=40 dev synth=0.9292、分型 {G1@5% 0.950,G1@20% 0.875,G2 0.850,G3 0.900} ⇒ gate=False（G1@20%、G2 不过）；"
     "B=80 dev synth=0.9437、分型 {G1@5% 0.975,G1@20% 0.900,G2 0.875,G3 0.900} ⇒ gate=False（G2 仍不过，nD=13）。"
     "对照判据集 {0.950,0.975,0.925,0.875}、留出集 {0.925,0.950,0.925,0.900} 双集均 gate=True。"
