     "G2 的 D-base 基（nD=6）经洞损后 r2 召回尤低（raw D=0.500/0.538），任何单一预处理均不占优（judge raw 0.925 vs dev raw 0.850–0.875；segmax 相反倒挂）。"
     "判读：候选仅把判据/留出集压线抬过 0.90（G2 边际 0.925 vs 0.90，≈1 SE 内），第三分区即回落 ⇒ 『K5 过线』在统计上不可靠；"
     "与本轮 #35『D 行与 G 族落同一条裁决』叠加，诚实的仪器状态仍为『未成』，是否放宽 G 门或改判据须 E5 裁决，禁止私自调判据凑数。"
