     "judge(0–5)：synth 0.954（A1.00 B1.00 C1 0.85 C2 0.975 C3 0.95 D0.95）/ G1@5% 0.950 / G1@20% 0.975 / G2 0.925 / G3 0.875 ⇒ 全过；"
