  "判据 0–5：synth 0.9708（A1.00 B1.00 C1 0.825 C2 1.000 C3 1.000 D1.000）；G1@5% 1.000 / G1@20% 0.925 / G2 0.975 / G3 0.975 ⇒ 五门全过。"
