  "T=262144 三区 C3 = 1.000/0.975/1.000，仅留出 1 例 C3→C2 残余；机理为 C 族准入已改用窗口不变效应量 R（R 跨窗近似恒定），不再随 n 抬升而误越门。"
  "三分区 synth 与 G 各门均不低于 T=131072 结果，无任何一区失守。"
  "边界（诚实）：C1 在判据区 T=262144 为 0.825（7 例 →NaN，低于 T=131072 的 0.875）——长窗下 x_min plateau 去偏使 n_eff 相对占比下降，"
  "功效略降但未误入他类、且 synth 总门远超线；属 C1 估计器层残余（#41③），不影响闸门。"
