  "关键发现①（薄线稳健性）：g300 G3 = 0.850 在 B=40 与 B=80 **逐位重现**（68/80=0.850），非小样本噪声——"
  "与 G 族内 6/40=0.15 的 D-base 结构性占比恰好吻合 ⇒ G3 残余失守为『G 族含 6/40 D-base 基过程』的结构性残余"
  "（#35/#42 同一裁决），非随机。该值恰在门线上（≥0.85），无误判风险但零裕度，诚实登记。"
  "关键发现②（新微混淆，诚实）：B=80 下出现 **D→B** 跨类误判各 1 例（判据/留出/g400，合计 3/480），B=40 时无——"
  "样本增多后暴露 D（有界超慢）局部近线性片段被 B（确定性斜坡）截获的边界；量级 ~0.6%，未触及任何闸门（D 召回仍 0.950–0.975）；"
  "机理属 D/B 判别式边界，本轮不改，登记待 E5。"
