  "阈值网格 g∈[0.40,0.70]：非-D 且满足 c1c2c3(cx<cx_A∧β≥β_D∧¬pl) 且 qr≤g 的**假阳恒为 0**；"
  "D 召回：α_mid 带单独 214/239 → 并集(α_mid∨qratio) 238–239/239。"
  "实装式（严格限定 D 行）：r2 子句『α_mid∈[alpha_D_lo,alpha_D_hi]』改为并集『α_mid∈带 ∨ qratio≤qratio_D』，新增 PRE 键 qratio_D=0.70"
  "（=clean-D 中位 0.368 与 clean-B 中位 1.001 的中点、取整至网格内，且该值下 FP=0）。"
  "影子树只读预测：D_alt 对基线**严格占优**（三分区 synth/G 五量齐升，如 holdout G3 0.883→0.933、synth 0.9708→0.9750；dev synth 0.9708→0.9792）；"
  "B 支守卫(qratio≥g) 无增益（D→B 仅 3/480≈0.6%、不触门）⇒ **不采纳**，保持最小改动。"
  "预登记验收口径：M1_k5_threeway.py（T=131072 与 262144，三分区 B=40）+ M1_k5_extseed.py（B=40 与 80，含 g200/g300/g400）"
