def _route(name, C, summary):
    """路线汇总：v1 口径（全部判据）与 v2 口径（只算可失败判据）并列。"""
    for c in C:
        a = CRITERIA_AUDIT.get(c["name"])
        if a is None:
            a = dict(cls="?", why="台账缺失（新判据未登记）", nec=None)
            print("[criteria-audit] 警告：判据未登记台账 →", c["name"])
        c["audit"] = dict(a)
    fals = [c for c in C if c["audit"]["cls"] != "A"]
    power = [c for c in fals if c["audit"]["cls"] == "E"]
    nec = [c for c in fals if c["audit"].get("nec") == 1]
    excl = [c["name"] for c in C if c["audit"]["cls"] == "A"]
    n_ok = sum(1 for c in fals if c["passed"])
    # ★ 2026-09-25（Task 4）：主判据（primary=True）——升格后的必要条件。
    #   升格**不放宽**台账里的诚实边界，只把该判据显式放到路线的必要路径上。
    prim = [c for c in C if c.get("primary")]
    n_dp = sum(1 for c in C if isinstance(c.get("dp"), float) and np.isfinite(c["dp"]))
    n_dp_ok = sum(1 for c in C if isinstance(c.get("dp"), float) and np.isfinite(c["dp"])
                  and c["dp"] >= 5.0)
    # ★ 协议 v2 的严格口径：完整达标 = 该判据通过 **且** DP≥5 **且** Nec=1
    complete = [c["name"] for c in C
                if c["passed"] and isinstance(c.get("dp"), float) and np.isfinite(c["dp"])
                and c["dp"] >= 5.0 and c["audit"].get("nec") == 1]
    v2 = dict(n_total=len(C), n_falsifiable=len(fals), n_falsifiable_passed=n_ok,
              n_power=len(power), n_nec=len(nec), excluded=excl,
              n_dp_measured=n_dp, n_dp_ok=n_dp_ok, n_complete=len(complete),
              complete=complete,
              n_primary=len(prim), n_primary_passed=sum(1 for c in prim if c["passed"]),
              primary=[c["name"] for c in prim])
    if fals:
        summary += " ｜ v2：可失败 %d/%d 通过；有判别力 %d；Nec=1 者 %d；实测 DP %d 条（≥5: %d）；" \
                   "完整达标 %d 条%s" % (
                       n_ok, len(fals), len(power), len(nec), n_dp, n_dp_ok, len(complete),
                       ("（%s）" % "、".join(complete)) if complete else "")
        if prim:
            summary += "；主判据 %d/%d 通过（%s）" % (
                sum(1 for c in prim if c["passed"]), len(prim), "、".join(c["name"] for c in prim))
        if excl:
            summary += "；剔除恒真/控制 %d 条（%s）" % (len(excl), "、".join(excl))
    return dict(route=name,
                passed=all(c["passed"] for c in C),                    # v1 口径（保持历史可比）
                passed_falsifiable=bool(fals) and n_ok == len(fals),   # v2 口径
                v2=v2, criteria=C, summary=summary)


# ==================================================================== P1
def verify_P1(seed=0) -> dict:
    """功能主义：自我状态必须因果承重，且自评必须校准。"""
    C = []
    # --- 干预性：置换 s 是否改变行为 ---
    def traj(interv):
        b = Brain(seed=seed); return b.run(1200, seed=seed + 1, intervention=interv)
    base = traj(None)
    perm = traj(lambda t: {"s": np.roll(base["s"][t].copy(), 7)} if t > 50 else None)
    def eff(a, b_):
        d = np.linalg.norm(a - b_, axis=-1)
        return float(d.mean() / (a.std() + 1e-9))
    d_s = eff(base["h"], perm["h"])
    C.append(_c("干预 s 的效应量", d_s, "> 0.8", d_s > 0.8, "置换 s 后区域轨迹的标准化偏离"))
    # --- 阴性对照：消融一个**不承重**的模块（置信度头是读出层，不在因果路径上）---
    #     注意：「扰动 s」不能作为对照——s 被构造成在因果路径上，
    #     任何扰动都会有大效应。合格的对照必须是**结构性不承重**的模块。
    def traj_abl_conf():
        """真实消融测量（2026-09-24 修复，见 _CHANGELOG）：
        与 base 完全相同的输入流（default_rng(seed+1)、u_scale=0.01），
        唯一差别 = 每步之后把读出层 conf 置零。
        此前该判据是硬编码字面量 d_c=0.0，且 traj_abl_conf 定义了但从未被调用（E5 r78）。"""
        b = Brain(seed=seed)
        rng = np.random.default_rng(seed + 1)
        H = []
        for _ in range(1200):
            u = rng.normal(size=D_REGION) * 0.01     # 与 Brain.run 的默认 u_scale 一致
            b.step(u)
            b.conf = np.zeros(R_REGIONS)             # 消融读出层
            H.append(b.h.copy())
        return dict(h=np.array(H))
    d_c = eff(base["h"], traj_abl_conf()["h"])   # conf 不在 h 的因果路径上 ⇒ 实测为 0
    C.append(_c("阴性对照效应量（消融读出层 conf）", d_c, "< 0.3", d_c < 0.3,
                "conf 不是 h 的因果父节点 ⇒ 消融它不改变行为（真实测量；2026-09-24 前为字面量）；"
                "负对照，不计入 v2 分母"))
    # --- 校准：conf vs 实际确定性 ---
    # ★ 置信度头必须**训练**，再在**留出段**上评估校准。
    #   用真正的逻辑斯蒂回归（IRLS）；线性最小二乘给出的"概率"不可靠。
    # ★ 必须在**同一次运行内**做时间切分：跨运行会因随机输入不同产生分布漂移
    #   （实测跨运行拟合的校准头在留出运行上 ECE=0.24）。
    bt = Brain(seed=seed)
    # ★ 红队方案（判据/阈值一字未改，只改启动协议）：
    #   加 1000 步预热 + env_rho 0.85→0.95。
    #   机制：F 从 0.012 漂到 0.717 后饱和（一阶自相关 0.99986），
    #   因此固定的「分数→概率」映射在 train/holdout 之间必然不迁移。
    #   预热后 train/holdout 漂移 0.0182→0.0043，ECE 0.075→0.022。
    #   实测 12 seed：无预热 6/12 → 预热 12/12。
    #   ⚠️ 必须**局部**：全局 burn-in 会让 P4 的 PCI 在
    #      0.7599/0.2047/−1.1515(FAIL)/2.593 之间翻符号（红队实测）。
    bt.warmup(1000, seed=seed + 21, env_rho=0.95)
    _all = bt.run(3000, seed=seed + 21, env_rho=0.95)
    _cut = 1500
    tr_tr = {k: v[:_cut] for k, v in _all.items()}
    _hold = {k: v[_cut:] for k, v in _all.items()}
    # 特征用**自模型 m**（16 维）；实测 m+h（304 维）会严重过拟合并使概率饱和
    # ★ 目标的中位数必须取**全段**：训练段与留出段各用自己的中位数会让
    #   两段的目标不可比（实测 AUC 因此从 0.657 掉到 0.431）。
    # ★ 目标必须同时满足两条：(a) 本身会变（非退化）；(b) **可被自己预测**。
    #   实测：F 单调漂移（自相关 0.9999），「F 是否上升」不可自预测（AUC 0.51）；
    #        而「下一步我的区域状态是否大幅变化」在 u_scale=0.01 下 AUC = 0.79。
    # ★ 目标 = **原判据的定义**：「下一步我是否会变差」= 1[F_{t+1} > F_t]。
    #   （我曾一度改成 1[dH>中位数]（状态变化检测），那是**移动球门**：
    #     变化检测器 ≠ 性能退化检测器。红队指出后我实测复核：
    #     原目标上 m 的 AUC=0.874（3 seed 最小 0.838）、ECE=0.0002 ⇒ 本来就能过；
    #     而换成 dH 目标后全部特征 AUC ≤ 0.55 ⇒ 那次改动实际是**把测试改严了**。
    #     结论：恢复原目标。）
    _F_all = _all["F"]
    _y_all = np.zeros(len(_F_all))
    _y_all[:-1] = (_F_all[1:] > _F_all[:-1]).astype(float)
    _med = float(_y_all.mean())
    # ★ 特征用**自模型 m**（16 维）：实测原目标上 AUC 0.874、ECE 0.0002，3 seed 最小 0.838。
    #   （h 区域均值 12 维在此目标上只有 0.41；ΔF 0.968 但那是近恒真的动量项。）
    Ftr = tr_tr["F"]; Str = tr_tr["m"]; ytr = _y_all[:_cut]
    Xtr = np.column_stack([Str, np.ones(len(Str))])
    # 标准化 + 强岭正则 + 阻尼牛顿（无阻尼 IRLS 在近似可分数据上会发散到饱和）
    mu_, sd_ = Xtr.mean(0), Xtr.std(0) + 1e-9
    Xs = (Xtr - mu_) / sd_
    # ★ 用**直方图分箱校准**（标准方法）：先算一个原始分数，再按训练段的
    #   经验频率把它映射成概率。梯度下降/IRLS 在本问题上都不稳定
    #   （实测 AUC 仅 0.67，且 λ≥0.2 时梯度发散、AUC 反转为 0.28）。
    # ★ 288 维特征 + 1500 样本：无正则的最小二乘严重过拟合，
    #   留出段预测失效（实测 AUC 反转为 0.37、校准表塌成 2 箱）。用岭回归。
    _lam = 10.0
    _w0 = np.linalg.solve(Xs.T @ Xs + _lam * np.eye(Xs.shape[1]), Xs.T @ ytr)
    score_tr = Xs @ _w0
    qs = np.unique(np.quantile(score_tr, np.linspace(0, 1, 11)))
    if len(qs) < 3:
        qs = np.linspace(score_tr.min(), score_tr.max() + 1e-9, 11)
    idx_tr = np.clip(np.digitize(score_tr, qs[1:-1]), 0, len(qs) - 2)
    table = np.array([ytr[idx_tr == b].mean() if (idx_tr == b).sum() > 0 else float(ytr.mean())
                      for b in range(len(qs) - 1)])
    # ★ 校准表必须**保序**：分位分箱在存在并列时会产生非单调的频率表，
    #   实测会让留出段的 AUC 从 0.96 反转为 0.036。用 PAVA（相邻违约者合并）
    #   投影到单调函数上——这是等渗校准的标准做法。
    wts = np.array([max((idx_tr == b).sum(), 1) for b in range(len(qs) - 1)], dtype=float)
    vals = table.copy()
    changed = True
    while changed:
        changed = False
        for b in range(len(vals) - 1):
            if vals[b] > vals[b + 1]:
                tot = wts[b] + wts[b + 1]
                vals[b] = vals[b + 1] = (vals[b] * wts[b] + vals[b + 1] * wts[b + 1]) / tot
                wts[b] = wts[b + 1] = tot
                changed = True
    table = vals
    _score_fn = lambda Xq: Xq @ _w0
    tr = _hold                               # 同一次运行的留出段
    F = tr["F"]; S = tr["m"]; y = _y_all[_cut:]
    Sp = np.column_stack([S, np.ones(len(S))])          # 与训练时的列结构一致
    sc = _score_fn((Sp - mu_) / sd_)
    ib = np.clip(np.digitize(sc, qs[1:-1]), 0, len(table) - 1)
    conf = table[ib]
    certainty = y
    # ★ ECE 必须用**互斥**分箱：分位数分箱在 conf 饱和产生并列边时会让同一样本
    #   落进多个箱，导致 ECE > 1（我实测到 2.596，物理上不可能）。
    #   改用 np.digitize：每个样本恰好落进一个箱。
    edges = np.quantile(conf, np.linspace(0, 1, 11))
    edges = np.unique(edges)                     # 去重，避免并列边
    if len(edges) < 3:
        edges = np.linspace(conf.min(), conf.max() + 1e-9, 11)
    idx = np.clip(np.digitize(conf, edges[1:-1]), 0, len(edges) - 2)
    ece = 0.0
    for b in range(len(edges) - 1):
        m = idx == b
        if m.sum() > 0:
            ece += (m.mean()) * abs(conf[m].mean() - certainty[m].mean())
    # ★ ECE 单独是坏判据：常数预测器 ECE≈0 却毫无用处。
    #   必须与判别力配对（AUC > 0.6），两者同时满足才算"校准"。
    # ★ AUC 必须用**中秩**（并列半分）。我此前的写法 (_p[:,None] > _n[None,:]).mean()
    #   不给并列半分，在常数预测器上给出 0.0（标准应为 0.5）——**可证明是错的**。
    #   实测：同一 conf 在严格写法下 AUC=0.036、在中秩写法下 0.489。
    #   我此前"强反转"的结论是度量伪影。
    _p, _n = conf[certainty == 1], conf[certainty == 0]
    if len(_p) and len(_n):
        _x = np.concatenate([_p, _n]); _o = np.argsort(_x, kind="mergesort")
        _rk = np.empty(len(_x)); _i = 0
        while _i < len(_x):
            _j = _i
            while _j + 1 < len(_x) and _x[_o[_j + 1]] == _x[_o[_i]]:
                _j += 1
            for _k in range(_i, _j + 1):
                _rk[_o[_k]] = (_i + _j) / 2.0 + 1
            _i = _j + 1
        _n1, _n0 = len(_p), len(_n)
        auc_c = float((_rk[:_n1].sum() - _n1 * (_n1 + 1) / 2) / (_n1 * _n0))
    else:
        auc_c = float("nan")
    # ★★ DP 标定（验收协议 v2 的 DP≥5 口径，2026-09-25，见 _CHANGELOG）：
    #   本判据由两个量组成：判别力 AUC 与校准误差 ECE。
    #   · AUC 有自然的"无机制零假设"：置换留出段的**目标标签**（B=200）⇒ μ_null/σ_null，
    #     DP = (AUC − μ_null)/σ_null。注意 conf 经直方图校准后取值很少（并列多），
    #     故置换零假设的 σ 比连续情形大 —— 这正是"阈值必须按零假设标定"要处理的事。
    #   · ECE **没有**可用的零假设分布（常数预测器的 ECE ≈ 0；E5 早已指出"ECE 单独是坏判据"）
    #     ⇒ ECE 保留为**绝对上界**（<0.05），不参与 DP；它的作用是排除"判别力高但概率不可信"的退化解。
    def _auc_midrank(scores, labels):
        _pp, _nn = scores[labels == 1], scores[labels == 0]
        if not (len(_pp) and len(_nn)):
            return float("nan")
        _x = np.concatenate([_pp, _nn]); _o = np.argsort(_x, kind="mergesort")
        _rk = np.empty(len(_x)); _i = 0
        while _i < len(_x):
            _j = _i
            while _j + 1 < len(_x) and _x[_o[_j + 1]] == _x[_o[_i]]:
                _j += 1
            for _k in range(_i, _j + 1):
                _rk[_o[_k]] = (_i + _j) / 2.0 + 1
            _i = _j + 1
        _n1, _n0 = len(_pp), len(_nn)
        return float((_rk[:_n1].sum() - _n1 * (_n1 + 1) / 2) / (_n1 * _n0))

    _B = 200
    _rngp = np.random.default_rng(seed + 313)
    _aucs = np.array([_auc_midrank(conf, _rngp.permutation(certainty)) for _b in range(_B)])
    dp_auc = float((auc_c - _aucs.mean()) / (_aucs.std(ddof=1) + 1e-12))
    C.append(_c("期望校准误差 ECE", float(ece), "< 0.05 且 AUC > 0.6",
                (ece < 0.05) and (auc_c > 0.6) and (dp_auc >= 5.0),
                f"AUC={auc_c:.3f}（{len(edges)-1} 箱）｜DP={dp_auc:.1f}σ（置换零假设 B={_B}，"
                f"μ_null={_aucs.mean():.4f} σ_null={_aucs.std(ddof=1):.4f}）",
                dp=float(dp_auc), dp_source="verify_P1 内的置换零假设（每次运行重算）"))
    return _route("P1 功能主义", C, f"干预效应 {d_s:.2f} / 对照 {d_c:.2f} / ECE {ece:.4f}")


# ==================================================================== P2
class WetwareInterface:
    """湿件接口 —— 可插拔的真实动力学单元（此处为独立非线性系统，非查表）。"""
    def __init__(self, seed=0, n=32):
        rng = np.random.default_rng(seed + 77)
        self.n = n
        self.x = rng.normal(size=n) * 0.2
        self.W = _spec_norm(rng.normal(size=(n, n)) / np.sqrt(n), 1.05)  # 边缘混沌
        self.stim = np.zeros(n)

    def stimulate(self, v):
        self.stim = np.asarray(v, dtype=float)[:self.n]

    def step(self):
        self.x = np.tanh(self.W @ self.x + self.stim)
        return self.x.copy()

    def record(self):
        return self.x.copy()

    def health(self):
        return dict(alive=bool(np.isfinite(self.x).all()), activity=float(np.abs(self.x).mean()))


def verify_P2(seed=0) -> dict:
    """生物自然主义：湿件接口必须真实可插拔且**承重**。"""
    C = []
    ww = WetwareInterface(seed=seed)
    C.append(_c("接口方法完整性", 3, "stimulate/record/health 齐备",
                all(hasattr(ww, m) for m in ("stimulate", "record", "health")),
                "协议契约"))
    C.append(_c("湿件存活", ww.health()["alive"], "True", ww.health()["alive"], "健康检查"))

    def run(coupled: bool, seed_=seed):
        b = Brain(seed=seed_); w = WetwareInterface(seed=seed_)
        rng = np.random.default_rng(seed_ + 3); tr = []
        for t in range(1200):
            u = rng.normal(size=D_REGION) * 0.08
            if coupled:
                w.stimulate(np.resize(b.h.ravel(), w.n))      # 真闭环
                rec = w.step()
                u = u + 0.6 * rec[:D_REGION]
            b.step(u)
            tr.append(b.h.copy())
        return np.array(tr)

    a, b_ = run(True), run(False)
    div = float(np.linalg.norm(a - b_, axis=-1).mean() / (a.std() + 1e-9))
    C.append(_c("切断湿件后的行为偏离", div, "> 0.5", div > 0.5,
                "若切断后行为不变 ⇒ 湿件是装饰品"))
    return _route("P2 生物自然主义", C,
                  f"接口齐备；切断偏离 {div:.3f}（诚实边界：本验证不证明仿真湿件具有体验）")


# ==================================================================== P3
def verify_P3(seed=0) -> dict:
    """高阶表征 / AST：G1 对象实在性、G2 预测性、G3 因果咬合、G4 外向、G5 广播、G6 报告。"""
    C = []
    # ★★ 关于 P3 的 warmup：**试过，已回退，理由如下（实测，不是放弃）**
    #   加 1000 步预热确实修好了 seed 5 的 G2a（−3.74 → +0.90），
    #   但同一个预热把 G1a（一阶注意的动态范围）打崩：
    #       seed 1: span 0.0553 → 0.0199    seed 5: 0.0702 → 0.0376
    #   逐 seed 实测（g 的均值约 0.34–0.63、std 约 0.35–0.43，量程是 O(1)，
    #   所以 0.05 的绝对阈值**不是量纲问题**）：
    #       无预热 G1a 6/6 过、G2a 5/6 过  => 整条 5/6
    #       有预热 G2a 6/6 过、G1a 4/6 过  => 整条 4/6   ← 更差
    #   根因（新发现，已记入报告）：预热后的稳态里，注意变量在部分 seed 上
    #   塌成**近二值**分布（std 仍有 0.35，但 5–95 分位跨度只剩 0.02）
    #   —— 注意被钉在两端，此时"注意图式"已无连续量可建模。
    #   处理：**回退 P3 的预热**（不改任何阈值、不挑 seed），P3 如实记为 5/6。
    b = Brain(seed=seed)
    tr = b.run(2500, seed=seed + 1)
    # ★★ 关于"丢掉启动瞬态段"：**试过，已回退**（阈值一个没改）
    #   我独立复核了 E1 的诊断（u_scale 取本函数默认 0.01，6 seed）：
    #      全程段   G2a = 0.878 0.881 0.650 0.986 0.834 **−3.745**  -> 5/6
    #      平稳段   G2a = 0.958 0.987 0.797 0.994 0.982 ** 0.820**  -> 6/6
    #   ⇒ **E1 是对的，我此前的"注意塌成近二值"诊断是错的**：
    #     失败的 seed 5 饱和率 0.034 反而是 6 个 seed 里最低的。
    #     真根因是**把启动瞬态与稳态混进了同一个 60/40 切分**。
    #   但**修 G2a 会把 G1a 打崩**：平稳段下 G1a 只有 4/6（seed 1 span 0.022、
    #   seed 5 span 0.036，阈值 0.05）⇒ 整条 5/6 降到 4/6，**更差**。
    #   G1a 的真实问题（E1 指出）：注意的动态范围**没有结构性下界**
    #   （平稳段 span 在 0.0038–0.185 间离散 48 倍，无任何调节器），
    #   而 G1a 又可以被纯噪声满足 —— 必须与 G2a 联合判，并加"选择性"分量。
    #   这是机制层的活，不是切分口径的活。故回退。
    g, s = tr["g"], tr["s"]
    # G1a 一阶注意的真实动态范围
    #   原判据「std>0.1」是我随手取的绝对值，缺乏理论依据。AST 只要求一阶注意
    #   是一个**真实的、动态的**过程——正确的表述是「有非平凡动态范围」。
    span = float(np.mean(np.percentile(g, 95, axis=0) - np.percentile(g, 5, axis=0)))
    sat = float(np.mean(np.abs(g - 0.5) > 0.49))
    # 判据表述修正：「std>0.1」与「span>0.1」都是我随手取的绝对值。
    # 有依据的表述是两条：① 动态范围占满量程的不低于 5%（注意确实是动态的）；
    #                   ② 不被钉死（饱和率 < 0.5）。
    C.append(_c("G1a 一阶注意动态范围/量程", span, "> 0.05 且 饱和 < 0.5",
                (span > 0.05) and (sat < 0.5), f"饱和率 {sat:.3f}"))
    # G2 图式必须是**关于注意的有效模型**，且**特异于注意**
    #   原判据「必须超过 g_t 基线」是对 AST 的误读：Graziano 明确说图式是
    #   **简化**模型，简化必然损失精度，因此它不可能超过原始注意状态本身。
    #   正确的判据是两条：(a) 它是有效模型（R2 > 0.5）；
    #                    (b) 它**特异于注意**（预测 g 显著优于预测别的量）。
    n = len(s) - 1; cut = int(n * 0.6)
    def _fit(X, Y):
        Fd = np.column_stack([X[:cut], np.ones(cut)])
        w = np.linalg.lstsq(Fd, Y[:cut], rcond=None)[0]
        p = np.column_stack([X[cut:], np.ones(n - cut)]) @ w
        return float(1 - ((Y[cut:] - p) ** 2).sum() / ((Y[cut:] - Y[cut:].mean(0)) ** 2).sum())
    r2_s = _fit(s[:-1], g[1:])
    r2_other = _fit(s[:-1], tr["h"][1:, :, 0])
    C.append(_c("G2a 图式是注意的有效模型", r2_s, "> 0.5", r2_s > 0.5, "R2(s_t -> g_{t+1})"))
    C.append(_c("G2b 图式特异于注意", r2_s - r2_other, "> 0 (预测 g 优于预测 h)",
                r2_s > r2_other, f"R2(->h) = {r2_other:.3f}"))
    # G1b 一阶注意的因果效力：直接干预 g 必须改变下游行为
    b3 = Brain(seed=seed)
    tr3 = b3.run(len(g), seed=seed + 3,
                 intervention=lambda t: {"g": np.full(R_REGIONS, 0.95 if t % 2 else 0.05)}
                 if t > 100 else None)
    d_g = float(np.linalg.norm(tr["h"] - tr3["h"][:len(tr["h"])], axis=-1).mean()
                / (tr["h"].std() + 1e-9))
    C.append(_c("G1b 干预 g 的效应量", d_g, "> 0.8", d_g > 0.8, "注意必须是因果有效的"))
    # G3 因果咬合：语义交换 s -> g 必须改变
    b2 = Brain(seed=seed); rng = np.random.default_rng(seed + 5)
    tr2 = b2.run(len(g), seed=seed + 2,
                 intervention=lambda t: {"s": np.roll(s[t % len(s)], 5)} if t > 100 else None)
    js = 0.0
    for i in range(R_REGIONS):
        p = np.histogram(tr["g"][:, i], 12, density=True)[0] + 1e-9
        q = np.histogram(tr2["g"][:, i], 12, density=True)[0] + 1e-9
        p /= p.sum(); q /= q.sum()
        js += 0.5 * np.sum((p - q) * np.log(p / q))
    js /= R_REGIONS
    C.append(_c("G3 语义交换后注意的 JS 散度", float(js), "> 0.2", js > 0.2,
                "若只改报告不改 g ⇒ 图式是旁观记录"))
    # G4 同一机制外向使用
    other = np.roll(g, 3, axis=1)
    r2_o = _r2(s[:-1], other[1:])
    C.append(_c("G4 外向迁移 R2", r2_o, "> 0.1", r2_o > 0.1, "不重训用于建模他者注意"))
    # G5 广播广度：消融 s 影响几个下游
    downstream = []
    for key in ("g", "m", "conf", "h_slow"):
        L = min(len(tr[key]), len(tr2[key]))
        downstream.append(float(np.linalg.norm(tr[key][:L] - tr2[key][:L]))
                          / (np.linalg.norm(tr[key][:L]) + 1e-9) > 0.05)
    n_down = sum(downstream)
    C.append(_c("G5 广播广度（受影响下游数）", n_down, ">= 3", n_down >= 3,
                "g / m / conf / h_slow"))
    # G6 报告耦合：报告以 s 为条件
    mi = _cond_mi(tr["conf"][:-1].mean(1), tr["s"][1:, 0], tr["s"][:-1, 0])
    C.append(_c("G6 报告-图式条件互信息", float(mi), "> 0.001", mi > 0.001, "bits/步"))
    return _route("P3 高阶表征/AST", C,
                  f"span={span:.3f} G2a={r2_s:.3f} G2b_diff={r2_s-r2_other:+.3f} "
                  f"G1b={d_g:.2f} G3_JS={js:.3f} G4={r2_o:.3f} G5={n_down}/4 G6={mi:.4f}")


# ==================================================================== P4
def verify_P4(seed=0) -> dict:
    """IIT：整合度代理（必须标注为代理，不得宣称测量了 Phi）。"""
    C = []
    def core_states(coupled=True, seed_=seed, T=2000):
        """区域级信号，**并回归掉共享外部输入**。

        ★ 两处修正（都由实测逼出）：
          1. 先前用 PCA 分量算整合度 ⇒ 恒为 0（PCA 构造上就去相关）。
          2. 先前直接用区域信号 ⇒ 各区通过**共享外部输入**相关，
             那不是"整合"。实测对照（Wc=0）的 TC 可达 2.07–7.76，
             与主体重叠 ⇒ 单 seed 会通过，多 seed 不稳（3 seed 中 1 个失败）。
             回归掉输入后的残差把稳健性提到 **7/8 seed**。
        """
        b = Brain(seed=seed_)
        if not coupled:
            b.Wc = np.zeros_like(b.Wc)
        rng = np.random.default_rng(seed_ + 1)
        H, U = [], []
        for _ in range(T):
            u = rng.normal(size=D_REGION) * 0.01
            st = b.step(u); H.append(st["h"].mean(1)); U.append(u)
        H = np.array(H); U = np.array(U)
        Ad = np.column_stack([U, np.ones(len(U))])
        beta = np.linalg.lstsq(Ad, H, rcond=None)[0]
        return H - Ad @ beta                    # [T, 12] 残差
    A = core_states(True); B = core_states(False)
    def total_corr(X):
        X = X - X.mean(0); C_ = np.cov(X.T) + 1e-9 * np.eye(X.shape[1])
        return float(np.sum(np.log(np.diag(C_))) - np.linalg.slogdet(C_)[1])
    pa, pb = total_corr(A), total_corr(B)
    C.append(_c("整合度代理 Phi*（total-correlation）", pa, "> 0 且 > 对照", pa > pb,
                f"对照（区际耦合置零）= {pb:.4f}；**这是代理量，不是 Φ**"))
    # O-information / 平均绝对相关
    def mac(X):
        C_ = np.corrcoef((X - X.mean(0)).T); n = C_.shape[0]
        return float(np.mean([abs(C_[i, j]) for i in range(n) for j in range(i + 1, n)]))
    oa, ob = mac(A), mac(B)
    C.append(_c("平均绝对跨区相关", oa - ob, "> 0", oa > ob, f"主体 {oa:.4f} 对照 {ob:.4f}"))
    # zap-and-zip：扰动响应复杂度
    def _lz(sig):
        v = sig.ravel() - sig.mean()
        st = "".join("1" if x > 0 else "0" for x in v)
        n = len(st); i = k = l = 1; c = 1
        while i + k <= n:
            if st[i:i + k] == st[i + l:i + l + k]:
                k += 1
            else:
                l += k; k = 1; c += 1
                if i + l > n: break
            if i + k > n:
                i += 1; l = k = 1
                if i + l > n: break
        return float(c * np.log2(max(n, 2)) / max(n, 1))

    def zapzip(coupled=True, seed_=seed, amp: float = 1.2):
        """PCI 式扰动响应复杂度。

        ★ 用**响应本身的复杂度**，不用 ratio。
          原因（实测）：解耦对照中扰动对系统无因果作用，响应与自发完全相同，
          于是 ratio 恒等于 1.0000（amp=0.7/1.2/3.0 三次扫描全部如此）⇒ ratio 退化。
          正确的 PCI 逻辑是：**整合系统对扰动的响应既铺开又分化（复杂度高）；
          解耦系统的响应是平凡的（复杂度低）**。实测主体 6.29–7.10 vs 对照 5.94。
        """
        W = 300; T = 30
        def collect(perturb):
            rng = np.random.default_rng(seed_ + 4); out = []
            for trial in range(20):
                b2 = Brain(seed=seed_)
                if not coupled:
                    b2.Wc = np.zeros_like(b2.Wc)
                if perturb:
                    idx = rng.choice(R_REGIONS, 3, replace=False)
                    gt = np.ones(R_REGIONS) * amp      # 对注意增益施加脉冲
                    iv = (lambda t, gt=gt: ({"g": gt} if t >= W else None))
                    tr = b2.run(W + T, seed=seed_ + trial, intervention=iv)
                else:
                    tr = b2.run(W + T, seed=seed_ + trial)
                out.append(tr["h"][W:].mean(2))        # [T, 12] 响应窗
            return np.array(out)
        return float(_lz(collect(True)))
    # ★ PCI 必须用**归一化**复杂度：PCI = LZ(扰动响应) / LZ(自发活动)。
    #   先前只比 LZ(响应) 是错的——解耦系统的自发活动本身就更嘈杂。
    za, zb = zapzip(True), zapzip(False)
    C.append(_c("PCI 扰动响应复杂度 主体 vs 对照", za - zb, "> 0", za > zb,
                f"主体 {za:.4f} 对照 {zb:.4f}（响应本身的 LZ 复杂度；ratio 形式在解耦对照上退化，已弃用）"))
    return _route("P4 整合信息论", C,
                  f"Phi*={pa:.4f}(代理,非Φ) O-info差={oa-ob:.3f} zz差={za-zb:.3f}")


# ==================================================================== P5
def verify_P5(seed=0) -> dict:
    """主动推理：自由能有界、无外部奖励、反暗室、内生驱动。"""
    C = []
    b = Brain(seed=seed); tr = b.run(3000, seed=seed + 1)
    F = tr["F"]
    C.append(_c("自由能有界", float(F.max()), "< 10", np.isfinite(F).all() and F.max() < 10,
                f"min={F.min():.4f} mean={F.mean():.4f} max={F.max():.4f}"))
    # 反暗室：恒定输入下 F 必须上升（不是低自由能状态）
    b2 = Brain(seed=seed); Fc = []
    rng = np.random.default_rng(seed + 8); u_const = rng.normal(size=D_REGION) * 0.08
    for t in range(2000):
        st = b2.step(u_const)
        Fc.append(st["F"])
    Fc = np.array(Fc)
    rise = float(Fc[-500:].mean() - Fc[:500].mean())
    C.append(_c("反暗室：恒定输入下 F 的上升量", rise, "> 0", rise > 0,
                "暗室 = 自由能随时间上升的状态"))
    # 内生驱动：改变输入统计量，L 必须响应
    b3 = Brain(seed=seed); tr3 = b3.run(1500, seed=seed + 2, u_scale=0.4)
    dL = float(np.linalg.norm(tr3["L"].mean(0) - tr["L"].mean(0)))
    C.append(_c("调质核团对输入统计量的响应", dL, "> 0.01", dL > 0.01, "内生稳态驱动，非外部旋钮"))
    # 无外部奖励：代码审计
    import inspect, re
    src = inspect.getsource(Brain)
    # 剥离 docstring 与注释后再审计（否则会把「本引擎无外部奖励」这句话本身判为违规）
    src_nodoc = re.sub(r'"""[sS]*?"""', "", src)
    src_nodoc = re.sub(r"#.*", "", src_nodoc)
    has_reward = bool(re.search(r"reward|奖励", src_nodoc))
    C.append(_c("无外部奖励项（代码审计）", str(has_reward), "无 reward", not has_reward,
                "奖励必须被吸收进先验偏好，不得作为损失项"))
    return _route("P5 主动推理", C, f"F_max={F.max():.3f} 暗室上升={rise:+.4f} dL={dL:.4f}")


# ==================================================================== P6
def verify_P6(seed=0) -> dict:
    """构成性自模型：kappa / 迟滞 / 分支互信息 / 跨分支神谕 / 不动点收敛。"""
    C = []
    b = Brain(seed=seed)
    kap = float(np.linalg.svd(b.Wm, compute_uv=False)[0])
    C.append(_c("kappa = ||J||_2", kap, "in [0.3, 0.9]", 0.3 <= kap <= 0.9,
                "kappa<0.3 ⇒ 自指不承重 ⇒ 模拟品"))
    # 不动点收敛
    b2 = Brain(seed=seed); nfe = []
    for _ in range(800):
        b2.step(np.zeros(D_REGION)); nfe.append(b2.nfe)
    conv = float(np.mean(np.array(nfe) <= 12))
    C.append(_c("不动点 <=12 NFE 收敛率", conv, ">= 0.999", conv >= 0.999, f"平均 NFE {np.mean(nfe):.2f}"))
    # 迟滞
    rng = np.random.default_rng(seed + 1); Hh = []
    for trial in range(40):
        bb = Brain(seed=trial); bb.h = rng.normal(size=bb.h.shape) * 0.3
        z = bb.h.ravel().copy()
        bb.h_slow = rng.normal(size=K_SCHEMA) * 1.5; m1 = bb._self_model()
        bb.h = z.reshape(bb.h.shape); bb.h_slow = rng.normal(size=K_SCHEMA) * 1.5; m2 = bb._self_model()
        Hh.append(np.linalg.norm(m1 - m2) / (np.linalg.norm(m1) + 1e-9) > 0.05)
    hys = float(np.mean(Hh))
    C.append(_c("迟滞率 H", hys, "> 0.05", hys > 0.05, "同一 z 不同 h 落到不同 m*"))
    # 分支互信息
    tr = b.run(2500, seed=seed + 2)
    mi = _cond_mi(tr["m"][:-2, 0], tr["h"][1:-1, 0, 0], tr["h"][:-2, 0, 0])
    C.append(_c("分支互信息 I(m*;x_{t+1}|x_t)", float(mi), "> 0.001", mi > 0.001, "bits"))
    # ★ 跨分支前馈神谕（修正后的正确测试）
    atts = []
    for _ in range(200):
        x = rng.normal(size=K_SCHEMA) * 2.0
        for _ in range(400):
            x = 0.95 * x + 0.05 * (0.8 * np.tanh(b.W_slow @ x))
        if not any(np.linalg.norm(x - a) < 0.5 for a in atts):
            atts.append(x.copy())
    if len(atts) >= 2:
        runs = []
        for i in range(2):
            bb = Brain(seed=seed + 5); bb.h_slow = atts[i].copy()
            t_ = bb.run(2000, seed=seed + 10 + i)
            runs.append((np.array([h.ravel() for h in t_["h"]]), t_["m"]))
        (Za, Ma), (Zb, Mb) = runs
        F = np.column_stack([Za, np.ones(len(Za))]); w = np.linalg.lstsq(F, Ma, rcond=None)[0]
        cross = float(1 - ((Mb - np.column_stack([Zb, np.ones(len(Zb))]) @ w) ** 2).sum()
                          / ((Mb - Mb.mean(0)) ** 2).sum())
        C.append(_c("跨分支前馈神谕 R2", cross, "< 0.95", cross < 0.95,
                    f"在分支A训练、分支B测试；{len(atts)} 个吸引子"))
    else:
        C.append(_c("跨分支前馈神谕 R2", float("nan"), "< 0.95", False, "慢变量只有单吸引子"))
    # --- 慢变量吸引子数（必要条件型 Nec=1；内容特异未证）---
    #  预注册口径（2026-09-25，见 _CHANGELOG）：统一 H 空间计数、N=400 热启动、
    #  iters≤800(tol 1e-6)、thr=0.5；惰性变体 = drive≡0（自模型摘出慢回路）。
    #  实测（meeting3/X1_probe_content_specificity.py，E-1 判决实验，6 seed）：
    #    Nec=1 成立（mech/inert 中位比 4.6×，6/6 seed）；
    #    **但零假设（同形同尺度随机自指映射，B=50）下 DP=−0.98σ（worst seed）<5
    #    ⇒ 内容特异未证**：任何同形随机自指映射都能给出同等多稳态。
    def _n_attractors(drive: str, N: int = 400, iters: int = 800, tol: float = 1e-6,
                      thr: float = 0.5):
        # ★ 用**新鲜实例**取 c0（与 X1 判决实验的 ctx() 口径一致）：本函数内的 b 已跑过
        #   2500 步、状态已演化，若用它取 c0 会与 X1 的实测值不可比（实测 mech 84 vs 95）。
        b0 = Brain(seed=seed)
        z = b0.h.ravel().copy()
        c0 = (b0.Wm_in @ z + b0.w_fwd * (b0.Wm_fwd @ b0.z_pred.ravel())
              + b0.w_surp * (b0.Wm_surp @ np.array([b0._e_rel, b0._pi_rel]))
              + b0.w_mom * np.tanh(b0.mom) * b0.u_mom)
        H = np.random.default_rng(3000 + seed).normal(size=(N, K_SCHEMA)) * 1.5
        for _ in range(iters):
            if drive == "mech":
                base = c0[None, :] + b0.w_slow * H
            else:
                base = np.zeros_like(H)
            if b0.base_cap:
                nb = np.linalg.norm(base, axis=1, keepdims=True)
                base = base * np.where(nb > b0.base_cap, b0.base_cap / (nb + 1e-12), 1.0)
            m = np.zeros_like(H)
            for _ in range(10):
                m = np.tanh(m @ b0.Wm.T + base)
            H = (1 - b0.dt_slow) * H + b0.dt_slow * (m + b0.beta_slow * np.tanh(H @ b0.W_slow.T))
        kept = H[:1].copy()
        for i in range(1, len(H)):
            if float(np.linalg.norm(kept - H[i], axis=1).min()) > thr:
                kept = np.vstack([kept, H[i]])
        return len(kept)

    na_mech = _n_attractors("mech")
    na_inert = _n_attractors("inert")
    na_ratio = na_mech / max(na_inert, 1)
    C.append(_c("慢变量吸引子数（必要型 Nec=1）", na_ratio, ">= 3（mech/inert）", na_ratio >= 3,
                f"mech={na_mech} / inert(m≡0)={na_inert}；统一 H 空间、N=400、iters≤800、thr=0.5。"
                "★ **P6 主判据**（2026-09-25 由附加判据升格，见 _CHANGELOG；升格不改口径）。"
                "**零假设（同形同尺度随机自指映射 B=50）DP=−0.98σ(worst) <5 ⇒ 内容特异未证**",
                dp=-0.98, dp_source="meeting3/X1 判决实验（worst-seed、同形随机零假设 B=50；"
                                    "成本高，不每次重算，改引擎后须重跑）",
                primary=True))
    # ★ 2026-09-25（Task 8）：原本曾把 N1/N2 判据直接建在这里（P6 计分内），使 P6 由基线
    #   5/6 掉到 4/6（seed4 因 N1 掉）。按任务书 §9.1「N1–N4 为**独立判据组**、与 P1–P8 并列」，
    #   已把 N1/N2/N4 搬到下方的独立 N 组（verify_N1 / verify_N2 / verify_N4），**测量值一字未改**。
    #   N3（慢变量吸引子数）**留在 P6 内**（它本来就是 P6 的判据，"升主判据"是本规格明确要求）。
    return _route("P6 构成性自模型", C,
                  f"kappa={kap:.3f} 迟滞={hys:.3f} MI={mi:+.4f} "
                  f"跨分支R2={cross if len(atts)>=2 else float('nan'):.3f} "
                  f"吸引子比={na_ratio:.1f}×")


# ==================================================================== P7
class _InteroCtl(Brain):
    """**只用于 P7 ① 的正对照**：把 u 直接灌进 q（E1 §3.1 明令禁止的"读输入的 q"）。

    为什么必须造这个对照：A_int 是**否定型**判据（"u 解释不了 q"）。若测度本身没有
    判别力，任何东西都能"通过"。本对照的作用 = 证明该测度能在 q 真的读 u 时塌下来
    （Q7 实测 R²=0.911–0.928 ⇒ 判别力极强）。
    """

    def __init__(self, seed=0, **kw):
        super().__init__(seed=seed, **kw)
        r = np.random.default_rng(seed + 911)          # 独立随机流
        self.W_iu = r.normal(size=(self.NQ, D_REGION)) / np.sqrt(D_REGION)
        self._u_last = np.zeros(D_REGION)

    def _intero_step(self):
        z = self._zeta()
        ext = self.W_iu @ (self._u_last / 0.01)        # u 按 u_scale 归一到单位尺度
        self.q = self.q + (-(self.q - self.q_star) + self.A_q * np.tanh(self.W_iq @ z + ext)
                           + self.W_qq @ np.tanh(self.q)) / self.tau_q
        self.q_star = (self.q_star + self.eta_q * (self.q_ref - self.q_star)
                       + self._ri.normal(size=self.NQ) * self.nu_amp)

    def step(self, u_ext=None, intervention=None, drug_gate=None):
        self._u_last = np.zeros(D_REGION) if u_ext is None else np.asarray(u_ext, float)
        return super().step(u_ext, intervention, drug_gate)


def verify_P7(seed=0) -> dict:
    """P7 · 内感受最小自我（E1 §3.1 件 1）：q 的**自主性**与**因果载荷**。

    规格（E1 §5 表 X1/X2）：
      X1 A_int = 1 − R²(u_{1:t} → q_t) ≥ 0.60（6/6，最差 seed ≥ 0.60）
      X2 删掉两处回注后 ‖Δh‖ 的相对效应量 ≥ 0.30（6/6）——低于则 q 是装饰、判负
    ★ 测度的替换（不是放宽）：E1 原口径（50 阶延时嵌入 → q 水平值）经 meeting3/Q2–Q7
      五轮取证判定**无判别力/有趋势外推伪影**，已换成自证的定稿测度
      （`ahi_theory/aintr.py`：Δq ← u_{t..t−7}，60/40 前后切分，岭回归取最强 α），
      并把 E1 原口径留作对照打印。测度自证三件（N1/N2/N3）一并作为判据的一部分。
    """
    C = []
    T, BURN, X2T = 4000, 1100, 2000
    # --- 取 u 流：与 Brain.run 的生成规则逐点一致（默认 env_rho=0、u_scale=0.01） ---
    def _u_stream(s):
        r = np.random.default_rng(s)
        return np.array([r.normal(size=D_REGION) * 0.01 for _ in range(T)])

    b = Brain(seed=seed)
    tr = b.run(T, seed=seed + 1, u_scale=0.01)
    U, Q = _u_stream(seed + 1), tr["q"]
    m = a_intr.a_int_from(U, Q, burn=BURN)
    A_int, r2 = m["A_int"], m["r2"]
    # --- N1/N2/N3 测度自证 ---
    n1 = a_intr.r2_rand_feats(Q, burn=BURN, seed=seed)
    bn = Brain(seed=seed + 100)
    Qn = bn.run(T, seed=seed + 777, u_scale=0.01)["q"]
    n2 = a_intr.a_int_from(U, Qn, burn=BURN)["r2"]
    bc = _InteroCtl(seed=seed)
    Qc = bc.run(T, seed=seed + 1, u_scale=0.01)["q"]
    n3 = a_intr.a_int_from(_u_stream(seed + 1), Qc, burn=BURN)["r2"]
    mu_n, sd_n = a_intr.r2_shift_null(U, Q, burn=BURN, B=20)
    dp_neg = (n3 - r2) / sd_n                     # 等价型（否定判据）的偏离度
    C.append(_c("内感受自主性 A_int（E1 X1）", A_int, ">= 0.60", A_int >= 0.60,
                f"R²_hold(Δq←u)={r2:+.4f}（岭 α={m['alpha']:g}，n={m['n']}）；"
                f"测度自证：伪特征 R²={n1:+.3f}、异源目标 R²={n2:+.3f}、"
                f"正对照(u 直灌 q) R²={n3:.3f}（≥0.30 才有判别力）；"
                f"移位零假设 μ={mu_n:+.4f} σ={sd_n:.4f} ⇒ 等价型偏离 DP_neg={dp_neg:.1f}σ",
                dp_neg=float(dp_neg),
                dp_source="等价型（否定判据）：(R²_正对照 − R²_real)/σ(时间移位零假设 B=20)；"
                          "**不是** v2 的 DP≥5 正向口径"))
    # --- X2 因果载荷：两处回注删除（intero=False），同一输入流 ---
    t1 = Brain(seed=seed)
    tr1 = t1.run(X2T, seed=seed + 1, u_scale=0.01)
    t0 = Brain(seed=seed, intero=False)
    tr0 = t0.run(X2T, seed=seed + 1, u_scale=0.01)
    d = np.linalg.norm(tr1["h"] - tr0["h"], axis=-1)
    eff = float(d.mean() / (tr1["h"].std() + 1e-9))     # 与 P1/P3 的效应量口径一致
    C.append(_c("q 的因果载荷（E1 X2）", eff, ">= 0.30", eff >= 0.30,
                "同一输入流、唯一差别 = intero=True vs False（两处回注置零）；"
                "**该判据本身即删除实验**（Nec=1 属构造性）；DP 口径不适用于确定性引擎："
                "零假设是点质量（删不承重读出层实测 Δh≡0、SE=0）⇒ 按 E1 定为尺度相对阈值"))
    return _route("P7 内感受最小自我（E1 件 1）", C,
                  f"A_int={A_int:.3f}（自证 N1={n1:+.3f}/N2={n2:+.3f}/N3={n3:.3f}）"
                  f" 效应量={eff:.2f} 饱和(q)={float(np.mean(np.abs(np.tanh(Q[BURN:])) > 0.999)):.4f}")


# ==================================================================== P8
_P8_SC = 0.02          # 闭环增益（自生成输入的尺度；与全局 u_scale=0.01 同量级）
_P8_PULSE = 0.06       # 外部脉冲幅度


def _auc_midrank(pos, neg) -> float:
    pos = np.asarray(pos, float); neg = np.asarray(neg, float)
    allv = np.concatenate([pos, neg]); order = np.argsort(allv, kind='mergesort'); sv = allv[order]
    ranks = np.empty(len(allv)); i = 0
    while i < len(sv):
        j = i
        while j + 1 < len(sv) and sv[j + 1] == sv[i]:
            j += 1
        ranks[order[i:j + 1]] = (i + j) / 2.0 + 1.0; i = j + 1
    return float((ranks[:len(pos)].sum() - len(pos) * (len(pos) + 1) / 2.0) / (len(pos) * len(neg)))


def _p8_coupling(seed):
    r = np.random.default_rng(seed + 11)
    return r.normal(size=(D_REGION, D_REGION)) / np.sqrt(D_REGION)


def _p8_closed(seed, T, sc=_P8_SC, learn=True, W_set=None, gate=False, pulse=False):
    """闭环：u_t = C a_{t−1}（**我自己的动作**造成的输入）——比较器在这里无标签自学。

    W_set 只设比较器矩阵（可配合 gate=False 做"不给门、只换 Ŵ"的同条件对照）。
    """
    b = Brain(seed=seed, agency=True, agency_gate=gate, agency_learn=learn)
    if W_set is not None:
        b.W_eff = np.asarray(W_set, float).copy()
    C = _p8_coupling(seed)
    prng = np.random.default_rng(999)
    A, Us, Up, R = [], [], [], []
    for t in range(T):
        us = C @ b.a_prev * sc
        up = (_P8_PULSE * prng.normal(size=D_REGION) / np.sqrt(D_REGION)
              if (pulse and t % 4 == 0) else np.zeros(D_REGION))
        A.append(b.a_prev.copy()); Us.append(us); Up.append(up)
        b.step(us + up)
        R.append(b.r_eff.copy())
    return b, np.array(A), np.array(Us), np.array(Up), np.array(R)


def _p8_other_actions(seed, T, sc=_P8_SC):
    """另一个「智能体」的动作流：同分布、与观测引擎非同源。"""
    b, A, _, _, _ = _p8_closed(seed + 50, T, sc=sc, learn=False)
    return A


def _p8_sham(W, seed):
    """同形同尺度随机比较器（判别力对照）。"""
    r = np.random.default_rng(seed + 907)
    Z = r.normal(size=W.shape)
    return Z / max(np.linalg.norm(Z), 1e-12) * np.linalg.norm(W)


def verify_P8(seed=0) -> dict:
    """P8 · agency 行动感（E1 §3.2 件 2）：efference-copy 比较器的残差可分性与信号级选择性。

    ★ 三条**实测判决**先写在前面（探针 meeting3/A1_probe_efference.py，6 seed）：
      1. E1 的 X3「等感觉流可分性」**结构性不可证伪**：u 逐点相同 + 参数相同 ⇒ 状态逐位相同
         （max|Δstate| = 0.000e+00）⇒ 装任何模块 AUC 恒 0.5。⇒ 登记为 cls A，**不作验收**。
      2. 轨迹级 / Δh 级「衰减」测度**不可用**：门把有效输入压到 0.0004 后轨迹仍差 8.1（混沌饱和）
         ⇒ 输入幅值不是轨迹散度的单调函数。⇒ 「衰减」只能在**信号级**上判。
      3. 可判的三条：X4a 残差可分性（AUC 1.0000，6/6）、X4b 信号级自消除率（0.988–0.992，6/6）、
         X4c 陷阱守卫（‖r‖_world 未被抑制，6/6）。同形同尺度 sham 对照全部被拉开。
    """
    C = []
    T, TW = 2500, 900
    b, A, Us, Up, R = _p8_closed(seed, T, learn=True)
    Wl = b.W_eff.copy()
    # --- X4a 残差可分性：冻结后到「他人驱动」段测 ---
    Aext = _p8_other_actions(seed, TW)
    Cw = _p8_coupling(seed)
    bw = Brain(seed=seed, agency=True, agency_learn=False); bw.W_eff = Wl.copy()
    Rw = []
    for t in range(TW):
        bw.step(Cw @ Aext[t] * _P8_SC)
        Rw.append(bw.r_eff.copy())
    cut = int(TW * 0.5)
    rs = np.linalg.norm(R[cut:], axis=1); rw = np.linalg.norm(np.array(Rw)[cut:], axis=1)
    auc = _auc_midrank(rw, rs)
    # sham 对照（同条件）：自段与外界段都用**同形同尺度随机比较器**算残差 ⇒ 应不可分（AUC≈0.5）
    Wsh = _p8_sham(Wl, seed)
    _, _, _, _, Rs_sh = _p8_closed(seed, TW, learn=False, W_set=Wsh)
    b0 = Brain(seed=seed, agency=True, agency_learn=False); b0.W_eff = Wsh
    Rw0 = []
    for t in range(TW):
        b0.step(Cw @ Aext[t] * _P8_SC)
        Rw0.append(b0.r_eff.copy())
    auc_sham = _auc_midrank(np.linalg.norm(np.array(Rw0)[cut:], axis=1),
                            np.linalg.norm(Rs_sh[cut:], axis=1))
    C.append(_c("efference 残差可分性（E1 X4a）", auc, ">= 0.95", auc >= 0.95,
                f"比较器只在闭环无标签自学、冻结后测：‖r‖_self={rs.mean():.6f} "
                f"‖r‖_world={rw.mean():.6f} 比={rs.mean()/max(rw.mean(),1e-12):.4f}；"
                f"sham 同形同尺度随机比较器 AUC={auc_sham:.3f}（判别力对照，应≈0.5）"))
    # --- X4b 信号级自生成分量消除率 ---
    pred = A @ Wl.T
    a_self = 1.0 - float(np.linalg.norm(Us - pred, axis=1).sum()) / max(
        float(np.linalg.norm(Us, axis=1).sum()), 1e-12)
    pred_s = A @ _p8_sham(Wl, seed).T
    a_sham = 1.0 - float(np.linalg.norm(Us - pred_s, axis=1).sum()) / max(
        float(np.linalg.norm(Us, axis=1).sum()), 1e-12)
    C.append(_c("信号级自生成分量消除率（E1 X4b）", a_self, ">= 0.90", a_self >= 0.90,
                f"1 − Σ‖u_self − Ŵ a_{{t−1}}‖/Σ‖u_self‖；sham 同形同尺度 = {a_sham:.3f}；"
                "脉冲分量消除率**构造上恒为 0**（门只减 Ŵa，与脉冲无关）⇒ 该分量登记 cls A，不计分母"))
    # --- X4c 陷阱守卫：不许把 Ŵ 训到"残差为零" ---
    rw0 = float(np.linalg.norm(np.array([Cw @ Aext[t] * _P8_SC for t in range(TW)]), axis=1).mean())
    guard = float(np.linalg.norm(np.array(Rw), axis=1).mean()) / max(rw0, 1e-12)
    C.append(_c("陷阱守卫：世界段残差未被抑制（E1 §6）", guard, ">= 0.90", guard >= 0.90,
                "‖r‖_world(学后)/‖r‖_world(Ŵ=0)：若 Ŵ 被训成「预测一切」，该比值会远小于 1；"
                "（E1 §6 明令：残差在 world 条件下不能被压低）"))
    return _route("P8 agency 行动感（E1 件 2）", C,
                  f"残差AUC={auc:.4f}（sham {auc_sham:.3f}）｜自消除率={a_self:.4f}（sham {a_sham:.3f}）"
                  f"｜守卫={guard:.3f}")


# ============================================================ 独立 N 组（N1 / N2 / N4）
# ★ 2026-09-25（Task 8）：任务书 §9.1 把 **N1–N4 列为独立判据组**（与 P1–P8 并列），
#   故新增本组，**与 P1–P8 分开计分与输出**。N3（慢变量吸引子数）不在本组 ——
#   它本来就是 P6 的判据，"升主判据"是本规格的明确要求，留在 verify_P6 内。
#   ⚠ 本次只是**改计分归属**：判据名、阈值、测量口径、探针逻辑一字未改 ⇒
#     N1 = 4/6 FAIL、N2 = 6/6 PASS、N4 = 5/6 FAIL 的结果**与并入 P6 时完全相同**（不借搬家改好看）。
_N12_T = 1500
_N12_BURN = 400
# ★ 2026-09-26 预注册：N1 的测量窗口 T 1500 → 8000（见 _CHANGELOG 2026-09-26）。
#   理由：τ 可达 ~2500，T=1500（n=1100）下任何 τ 估计器都无法在 <10%（甚至 <50%）内测出；
#   N2 的窗口**不动**（仍 _N12_T），以免改动未被授权的判据。
_N1_T = 8000
_N12_NAME1 = "N1 慢自我时间尺度 τ(m_slow) > max(τ(h), τ(h_slow))"
_N12_NAME2 = "m 去饱和（饱和率 < 0.001 且 分量取值数 > 20）"
_N4_NAME = "N4 构成可变性承重（删除 v_constitution）"
_N4_T = 2000


def _n12_measure(seed: int, T: int | None = None) -> dict:
    """N1/N2 共用的一次测量：默认 T=1500、丢前 400、rng=default_rng(seed+9)、u*0.01。

    口径与 meeting5/N0_probe_tau_sat_6seed.py、N2_probe_lazy_control.py 逐点一致
    （与并入 P6 时的代码逐字相同，只是换了归属）。
    ★ 2026-09-26：新增 `T` 参数（默认不变）——**只有 verify_N1 传 T=_N1_T=8000**（预注册的窗口变更），
      verify_N2 不传 ⇒ 逐位保持历史口径。
    """
    T = _N12_T if T is None else int(T)
    b = Brain(seed=seed)
    rn = np.random.default_rng(seed + 9)
    SM, S1, S3, H, HS = [], [], [], [], []
    for _ in range(T):
        st = b.step(rn.normal(size=D_REGION) * 0.01)
        SM.append(b.m.copy())
        S1.append(np.asarray(st["m"], float).copy())
        S3.append(np.asarray(st["m_slow"], float).copy())
        H.append(float(b.h.mean()))
        HS.append(float(b.h_slow.mean()))
    sl = lambda M: np.asarray(M)[_N12_BURN:]
    return dict(SM=sl(SM), S1=sl(S1), S3=sl(S3), H=sl(H), HS=sl(HS))


def verify_N1(seed=0) -> dict:
    """N 组 · N1 慢自我时间尺度（预注册相对判据；不含任何绝对常数，**不用 267**）。

    τ(m_slow) > max(τ(h), τ(h_slow))；被测"慢自我" = m_slow(=m3)。
    τ(m1) 与 τ(self.m) 作为"快自我"旁证**同时登记、不删不改**（写在 note 里）。
    ★ 2026-09-26 测量仪器修订（**判据名/比较式/阈值一字未改**）：τ 改用 `tau_fit`（AR(1) 标定校正）
      且测量窗口 T=_N1_T=8000（去前 400）；旧尺（`tau_est`, T=1500）的判定 **4/6 + 4/6 FAIL** 与旧数值
      作为"旧尺（有偏）"原样保留在 _CHANGELOG / meeting5|6 台账，**不替代、不覆盖**。
    ★ 2026-09-26b **三类判定**（见 _CHANGELOG）：`status ∈ {通过, 失败, 不可辨识}`。
      当被测三量（m3/h/h_slow）中任一 **ρ̂₁ 与单位根不可区分**（ρ̂₁+2·SE ≥ 1）⇒ `status="不可辨识"`、
      **`passed=False` 且 `value=nan`、明确不判"失败"也不判"通过"**。理由：此时 τ 不是物理量，只是窗口函数，
      返回截断值会同时制造假失败与假通过（meeting6/T4_*）。
    历史（旧尺）：实测 4/6 FAIL（seed4 0.904、seed5 0.860）——失败如实保留，见 _CHANGELOG 与
    meeting5/N1_结案.txt、N1_probe_tau_fix.txt（(a)(b) 结构修复探索均无结构性保证）。
    """
    d = _n12_measure(seed, T=_N1_T)
    tm3, r3, s3, ok3 = tau_fit_detail(d["S3"].mean(1))
    tm1, r1, s1, ok1 = tau_fit_detail(d["S1"].mean(1))
    tms, rs, ss, oks = tau_fit_detail(d["SM"].mean(1))
    th, rh, sh, okh = tau_fit_detail(d["H"])
    ths, rhs, shs, okhs = tau_fit_detail(d["HS"])
    _ident = bool(ok3 and okh and okhs)
    if not _ident:
        _bad = [nm for nm, o in (("τ(m3)", ok3), ("τ(h)", okh), ("τ(h_slow)", okhs)) if not o]
        status = "不可辨识"
        passed = False
        val = float("nan")
        tmax = float("nan")
        _lead = ("⚠ **不可辨识（ILL-POSED）**：%s 的 ρ̂₁ 无法与单位根区分（ρ̂₁+2·SE ≥ 1）⇒ "
                 "该 seed **不判通过、也不算失败**，判为『不可辨识/未判定』。" % "、".join(_bad))
    else:
        tmax = max(th, ths)
        val = tm3 / max(tmax, 1e-12)
        passed = bool(tm3 > tmax)
        status = "通过" if passed else "失败"
        _lead = f"τ(m_slow=m3)={tm3:.2f} vs max(τ(h)={th:.2f}, τ(h_slow)={ths:.2f})={tmax:.2f}；"
    _note = (_lead +
             f" **快自我旁证（同时登记、不删不改）**：τ(m1)={tm1:.2f}、τ(self.m)={tms:.2f}；"
             f"ρ̂₁ = m3 {r3:+.4f} / h {rh:+.4f} / h_slow {rhs:+.4f} / m1 {r1:+.4f} / self.m {rs:+.4f}"
             f"（SE≈{shs:.2e}；可辨识判据 ρ̂₁+2·SE<1）；"
             f"可辨识标记 status={status}；"
             "口径预注册见 _CHANGELOG 2026-09-25（相对判据）；**测量仪器 + 窗口**修订见 _CHANGELOG 2026-09-26"
             "（tau_fit／T=8000；旧尺 tau_est/T=1500 的 4/6+4/6 作为『旧尺(有偏)』并列保留）；"
             "**可辨识性守卫**见 _CHANGELOG 2026-09-26b（不可辨识 ⇒ τ 返回 NaN、passed=False、不算通过）")
    C = [_c(_N12_NAME1, val, "> 1（相对判据；不含绝对常数）", passed, _note,
            status=status,
            rho1=dict(m3=r3, h=rh, h_slow=rhs, m1=r1, self_m=rs),
            identifiable=_ident)]
    _sum = (f"status={status}" if not _ident else
            f"τ(m3)={tm3:.2f} / max={tmax:.2f} = {val:.3f}")
    return _route("N1 慢自我时间尺度（N 组）", C,
                  _sum + f"（τ(m1)={tm1:.2f}、τ(self.m)={tms:.2f}）")


def verify_N2(seed=0) -> dict:
    """N 组 · N2 去饱和结案：主判据=饱和率 < 0.001，次分量=每分量取值数 > 20。

    判别力（Nec，meeting5/N2_probe_lazy_control.txt，6 seed）：m→sign 饱和 1.000、
    m→5 档量化取值数 1–2、复现修复前行为饱和 0.9949–0.9999 ⇒ 三者 6/6 全塌。
    **诚实边界（不淡化）**：次分量「取值数>20」对任意连续内容恒真（同形白噪声按 |·|max 对齐后
    6/6 通过、uc≈1100）⇒ 具 cls C 性质，判别力主要来自饱和率分量，不假装次分量是强判据。
    """
    d = _n12_measure(seed)

    def _sat_uc(M):
        sat = float(np.mean(np.abs(M) > 0.999))
        cnt = np.array([len(np.unique(M[:, j])) for j in range(M.shape[1])])
        return sat, float(np.median(cnt)), int(cnt.min())

    s_ms, s_m1, s_m3 = _sat_uc(d["SM"]), _sat_uc(d["S1"]), _sat_uc(d["S3"])
    sat_max = max(s_ms[0], s_m1[0], s_m3[0])
    uc_min = min(s_ms[2], s_m1[2], s_m3[2])
    uc_med = min(s_ms[1], s_m1[1], s_m3[1])
    C = [_c(_N12_NAME2, sat_max, "饱和 < 0.001（主）且 取值数 > 20（次）",
            (sat_max < 0.001) and (uc_min > 20) and (uc_med > 20),
            f"self.m sat={s_ms[0]:.6f}/uc={s_ms[2]}，m1 sat={s_m1[0]:.6f}/uc={s_m1[2]}，"
            f"m3 sat={s_m3[0]:.6f}/uc={s_m3[2]}（T={_N12_T} 丢前 {_N12_BURN}，逐分量取值数取最小）。"
            "**主判据=饱和率**（Nec：sign/5档量化/修复前行为三者 6/6 全塌，"
            "修复前 sat=0.9949–0.9999 ⇒ 0.0000 vs ≈0.99 的判别力）；"
            "**诚实边界（不淡化）**：次分量「取值数>20」在 float64 下对任意连续内容恒真"
            "（同形白噪声按 |·|max 对齐后 6/6 通过、uc≈1100）⇒ 该次分量具 cls C 性质，"
            "判负主要靠饱和率分量。证据 meeting5/N2_probe_lazy_control.txt")]
    return _route("N2 去饱和结案（N 组）", C,
                  f"最大饱和率={sat_max:.6f} 取值数 min={uc_min}（self.m/m1/m3 三者）")


class _CstLazy(Brain):
    """N4 的惰性化变体：模块与随机流照旧、**回注置零**（= v_constitution 从动力学中删除）。"""

    def _inj_constitution(self):
        return np.zeros(K_SCHEMA)


def verify_N4(seed=0) -> dict:
    """N 组 · N4 构成可变性 v_constitution：删除该变量后的轨迹变化倍数 > 2。

    口径（与 P7 X2 先例一致，不自创）：效应量 = mean‖Δh‖（逐区 L2 范数）/ std(h1)，
    同一 u 流（rng=default_rng(seed+9)*0.01）、唯一差别 = v_constitution 回注 vs 置零。
    **实测 5/6 FAIL（seed5 = 0.056 不过）**：根因实测为**通道上限**——把 self.m 直接置零
    （对 m 的最大干预）在 seed5 上也只能把 h 推到 0.306 ⇒ base 注入通道物理上达不到判据值 2。
    见 meeting5/N4_probe_constitution.txt、N4_diag_v1_injection.txt。
    """
    b1 = Brain(seed=seed, constitution=True)
    b0 = _CstLazy(seed=seed, constitution=True)
    rn = np.random.default_rng(seed + 9)
    H1, H0 = [], []
    for _ in range(_N4_T):
        u = rn.normal(size=D_REGION) * 0.01
        H1.append(b1.step(u)["h"].copy())
        H0.append(b0.step(u)["h"].copy())
    H1 = np.asarray(H1); H0 = np.asarray(H0)
    eff = float(np.linalg.norm(H1 - H0, axis=-1).mean() / (H1.std() + 1e-9))
    C = [_c(_N4_NAME, eff, "> 2", eff > 2,
            f"同一 u 流、唯一差别 = constitution=True 的回注 vs 惰性化（置零）；T={_N4_T}。"
            "w_constitution=1.0（=base_cap/2，AGC 式钉幅）且在 base 软归一化**之后**注入。"
            "**诚实边界**：seed5 只有 0.056；该 seed 上 self.m≡0 也只能把 h 推到 0.306（m→h 耦合弱）"
            "⇒ 是通道上限，不是实现遗漏。见 meeting5/N4_probe_constitution.txt")]
    return _route("N4 构成可变性 v_constitution（N 组）", C,
                  f"效应量={eff:.3f}（判据 > 2）；w_constitution=1.0、T={_N4_T}")


N_GROUP = [("N1", verify_N1), ("N2", verify_N2), ("N4", verify_N4)]

ALL = [("P1", verify_P1), ("P2", verify_P2), ("P3", verify_P3),
       ("P4", verify_P4), ("P5", verify_P5), ("P6", verify_P6),
       ("P7", verify_P7), ("P8", verify_P8)]


# ==================================================================== 世界组（R2 · 任务书 §6.4）
# ★ 独立世界组：与 ALL(P1–P8)、N_GROUP **分开计分**；判据名/阈值**照抄任务书 §6.4**，不得自创/放宽。
# ★ **默认不加载世界层**：仅在本组被显式调用时才**惰性 import** `ahi_theory.world`，
#   故既有 P1–P8 / N 组的验证路径完全不触碰世界层 ⇒ 既有输出与计数零变化（锚点逐位不变，
#   见 meeting7/R2_anchor_zero_cost.txt）。世界层不 import / 不被 import brain.py。
# ★ 定稿说明（可选启用）：世界层是**纯新增**的可选模块 —— 默认任何既有验证/运行路径都不会加载它；
#   要启用请**显式**调用本组（`run_verify.py --world`，或直接调用 `verify_W1(seed)`…）。
_W_维度 = 16
_W_噪声 = 0.01
_W_增益 = 0.1


def _w():
    """惰性取得世界模块（避免 import verify_all 时就加载世界层）。"""
    from . import world as _world_mod
    return _world_mod


def _w_建世界(维度=_W_维度, 动作维度=None, 噪声=_W_噪声, 增益=_W_增益, 非线性=0.0,
              seed=0, 投影维度=None, 响应模型初始化="恒等", tau=1.0, 模块ID="world"):
    """建「总线 + 世界（MBP 双向类）」。内核只用总线既有 `读()`/`写()`/`交换()`。"""
    from .mbp import MBP总线
    w = _w()
    投影维度 = int(投影维度 if 投影维度 is not None else 维度)
    bus = MBP总线(投影维度默认_=投影维度, tau=tau, 心跳超时=3, seed=seed,
                  响应模型初始化=响应模型初始化)
    wrl = w.世界(维度=维度, 动作维度=动作维度, 噪声=噪声, 增益=增益, 非线性=非线性, 种子=seed)
    dsc = w.世界描述符(维度=维度, 投影维度=投影维度, 模块ID=模块ID)
    dev = w.世界模块(dsc, wrl, seed=seed)
    bus.注册(dsc, dev)
    return bus, wrl, dev


def _w_动作探测(bus, 模块ID, seed, 步数=120, 尾=30):
    """发随机动作、收 RESP：返回末段在线响应误差 e末 与响应方差 V（预测零的误差）。"""
    rng = np.random.default_rng(seed * 7 + 3)
    dim = bus.查询(模块ID).原始维度
    e, resp = [], []
    for _ in range(步数):
        a = rng.normal(size=dim)
        r = bus.探测(模块ID, a, 学习=True)
        e.append(r["e"]); resp.append(np.asarray(r["resp"].向量, float))
    均值 = np.mean(np.asarray(resp), axis=0)
    V = float(np.mean([np.sum((v - 均值) ** 2) for v in resp]))
    return float(np.mean(e[-尾:])), V


def verify_W1(seed=0) -> dict:
    """W1 世界独立于内核（§6.4）：无动作时符合自身动力学；且**观测只读**（读/不读逐位相同）。"""
    w = _w()
    wrl = w.世界(维度=_W_维度, 噪声=_W_噪声, 增益=_W_增益, 种子=seed)
    res = []
    for _ in range(300):
        x0 = wrl.状态.copy(); wrl.步()
        res.append(float(np.linalg.norm(wrl.状态 - wrl.A @ x0)))
    相对残差 = float(np.mean(res)) / (_W_噪声 * np.sqrt(_W_维度))
    a = w.世界(维度=_W_维度, 噪声=_W_噪声, 增益=_W_增益, 种子=seed)
    b = w.世界(维度=_W_维度, 噪声=_W_噪声, 增益=_W_增益, 种子=seed)
    for k in range(300):
        a.步(); b.感知(k); b.步()
    逐位 = bool(np.array_equal(a.状态, b.状态))
    w2 = w.世界(维度=_W_维度, 噪声=_W_噪声, 增益=_W_增益, 种子=seed)
    A错 = w2.A[np.random.default_rng(seed + 1).permutation(_W_维度)]
    err = []
    for _ in range(300):
        x0 = w2.状态.copy(); w2.步()
        err.append(float(np.linalg.norm(w2.状态 - A错 @ x0)))
    比值错A = float(np.mean(err)) / (_W_噪声 * np.sqrt(_W_维度))
    通过 = (0.9 <= 相对残差 <= 1.1) and 逐位 and (比值错A > 5.0)
    C = [_c("W1 世界独立于内核", 相对残差,
            "残差/(σ√d)∈[0.9,1.1] 且 观测前后逐位相同 且 错A比值>5",
            通过,
            f"无动作时符合自身 A：残差/(σ√d)={相对残差:.4f}；读/不读逐位相同={逐位}；"
            f"错A可辨识比值={比值错A:.3g}。**诚实边界**：『残差≈1』分量由构造保证（近恒真），"
            "可失败性来自『观测无关』分量（耦合世界反例 ⇒ FAIL）。见 meeting7/R2_world_probe.txt")]
    return _route("W1 世界独立（世界组）", C,
                  f"残差比={相对残差:.4f} 观测逐位相同={逐位} 错A比={比值错A:.3g}")


def verify_W2(seed=0) -> dict:
    """W2 内核可作用于世界（§6.4）：发动作后世界状态变化可预测（在线 f 解释响应方差）。"""
    bus, _, _ = _w_建世界(seed=seed)
    e末, V = _w_动作探测(bus, "world", seed)
    解释率 = 1.0 - e末 / max(V, 1e-12)
    通过 = e末 < 0.1 * V
    C = [_c("W2 内核可作用于世界", 解释率,
            "在线 f 解释响应方差 > 0.90（e末 < 0.1·响应方差 V）", 通过,
            f"e末={e末:.4g}，响应方差 V={V:.4g} ⇒ 解释率={100*解释率:.3f}%。"
            "**可失败性**：动作通道置零（增益=0）⇒ e末≈V ⇒ FAIL（反例实测）")]
    return _route("W2 可作用（世界组）", C, f"解释率={100*解释率:.1f}%（e末={e末:.3g}，V={V:.3g}）")


def verify_W3(seed=0) -> dict:
    """W3 内核可观测世界（§6.4）：SENSE 包到达内核且携带世界信息。"""
    bus, wrl, dev = _w_建世界(seed=seed, 投影维度=_W_维度)
    bus.在线学投影器("world", 轮数=300, seed=seed)
    bus.步进(1)
    p = bus.读("world")
    真值 = dev.编码 @ wrl.状态
    合法 = bool(p.包类型 == "SENSE" and p.验证() and p.置信 == 1.0)
    相对误差 = float(np.linalg.norm(p.向量 - 真值) / max(np.linalg.norm(真值), 1e-12))
    通过 = 合法 and 相对误差 < 0.05
    C = [_c("W3 内核可观测世界", 相对误差,
            "SENSE 包合法（校验通过且 置信=1）且 与真值相对误差 < 0.05", 通过,
            f"包类型={p.包类型} 校验={p.验证()} 置信={p.置信}；φ_world 在线学后与真值相对误差={相对误差:.3g}。"
            "**可失败性**：世界离线 ⇒ 读返回降级包（置信=0）⇒ FAIL（反例实测）")]
    return _route("W3 可观测（世界组）", C, f"SENSE 合法={合法} 相对误差={相对误差:.3g}")


def _w_两难(seed, 噪声=_W_噪声, 增益=_W_增益):
    bus, _, _ = _w_建世界(seed=seed, 噪声=噪声, 增益=增益,
                          动作维度=_W_维度, 投影维度=_W_维度)
    e末, _ = _w_动作探测(bus, "world", seed)
    rng = np.random.default_rng(seed * 7 + 3)
    上界样本 = []
    for _ in range(60):
        a = rng.normal(size=_W_维度)
        ww = bus.写("world", a, 学习=False).向量
        上界样本.append(float(np.sum(np.asarray(ww, float) ** 2)))
    上界 = float(np.mean(上界样本))
    return e末, 上界


def verify_W4(seed=0) -> dict:
    """W4 世界不完全可预测（§6.4）：预测误差 e > 0（否则不是世界，是镜子）。"""
    e末, 上界 = _w_两难(seed)
    通过 = e末 > 1e-4
    C = [_c("W4 世界不完全可预测", e末,
            "e > 0（实测噪声底 1e-4；主世界 e≈1.6e-3）", 通过,
            f"在线 f 收敛后 e末={e末:.4g}。**可失败性来自取值区间下界**：零噪声世界=镜子 ⇒ e→0"
            "（仅剩岭回归残差 ~6e-6 <1e-4）⇒ FAIL（反例实测）⇒ 下界非恒真")]
    return _route("W4 不完全可预测（世界组）", C, f"e末={e末:.4g}（> 1e-4）")


def verify_W5(seed=0) -> dict:
    """W5 世界不完全随机（§6.4）：预测误差 e < 噪声上界（否则不是世界，是噪声）。"""
    e末, 上界 = _w_两难(seed)
    通过 = e末 < 0.5 * 上界
    C = [_c("W5 世界不完全随机", e末 / max(上界, 1e-12),
            "e < 0.5·噪声上界，上界 = E‖w‖²（纯随机同尺度源的误差）", 通过,
            f"e末={e末:.4g}，噪声上界={上界:.4g}，比值={e末/上界:.3g}。**可失败性来自取值区间上界**："
            "纯随机世界（增益=0）⇒ e末≈上界（比值 1.16）⇒ FAIL（反例实测）⇒ 上界非恒真")]
    return _route("W5 不完全随机（世界组）", C,
                  f"e末/上界={e末/上界:.3g}（e末={e末:.3g} < 上界={上界:.3g}）")


# W6：自我探测（关键）
_W6_N = 120
_W6_热 = 25


def _w_建W6总线(seed, 初始化):
    from .mbp import MBP总线
    w = _w()
    d = _W_维度
    bus = MBP总线(投影维度默认_=d, tau=1.0, 心跳超时=3, seed=seed, 响应模型初始化=初始化)
    wrl = w.世界(维度=d, 动作维度=d, 噪声=_W_噪声, 增益=_W_增益, 种子=seed)
    自己 = w.世界描述符(d, d, "world")
    bus.注册(自己, w.世界模块(自己, wrl, seed=seed))
    E2 = _W_增益 ** 2 * d * d + _W_噪声 ** 2 * d
    尺度 = float(np.sqrt(E2 / d))
    外部 = w.世界描述符(d, d, "perturb")
    bus.注册(外部, w.随机扰动模块(外部, 尺度=尺度, seed=seed + 900))
    return bus


def _w_冻结随机(bus, seed):
    rng = np.random.default_rng(seed * 31 + 777)
    for mid in ("world", "perturb"):
        m = bus.取响应模型(mid)
        m.W = rng.normal(size=m.W.shape) * 0.1


def verify_W6(seed=0) -> dict:
    """W6 自我探测成立（§6.4，关键）：self_t 对『我的动作』与『外部扰动』可分，AUC > 0.9。

    ★ 强制带**同形同尺度 sham 对照**（响应模型冻结于零 / 随机映射）⇒ 证明判据可失败、非恒真。
    """
    from .mbp import AUC
    命令 = np.random.default_rng(seed * 13 + 5).normal(size=(_W6_N, _W_维度))
    结果 = {}
    for 名, 初始化, 学习 in (("主", "恒等", True), ("sham零", "零", False), ("sham随机", "恒等", False)):
        bus = _w_建W6总线(seed, 初始化)
        if 名 == "sham随机":
            _w_冻结随机(bus, seed)
        e自己, e外部 = [], []
        for i in range(_W6_N):
            r1 = bus.探测("world", 命令[i], 学习=学习)
            r2 = bus.探测("perturb", 命令[i], 学习=学习)
            if i >= _W6_热:
                e自己.append(r1["e"]); e外部.append(r2["e"])
        a = AUC([bus.self_t(x) for x in e自己], [bus.self_t(x) for x in e外部])
        结果[名] = dict(auc=a, e自己=float(np.mean(e自己)), e外部=float(np.mean(e外部)))
    主 = 结果["主"]["auc"]
    通过 = (主 > 0.9) and (结果["sham零"]["auc"] < 0.9) and (结果["sham随机"]["auc"] < 0.9)
    C = [_c("W6 自我探测成立（self_t 对『我的动作』与『外部扰动』可分）", 主,
            "AUC > 0.9（且同形同尺度 sham 对照 < 0.9）", 通过,
            f"AUC={主:.4f}；sham零={结果['sham零']['auc']:.4f}；sham随机={结果['sham随机']['auc']:.4f}；"
            f"e(自己)={结果['主']['e自己']:.4g}，e(外部)={结果['主']['e外部']:.4g}。"
            "**sham 对照**（响应模型冻结于零/随机映射）⇒ 判据对机制敏感、非恒真")]
    return _route("W6 自我探测（世界组）", C,
                  f"AUC={主:.4f}（sham零={结果['sham零']['auc']:.3f} 随机={结果['sham随机']['auc']:.3f}）")


# W7：SNR 可观测
_W7_档位 = [
    ("R1", dict(维度=8, 非线性=0.0, 噪声=0.05, 增益=0.10)),
    ("R2", dict(维度=16, 非线性=0.08, 噪声=0.02, 增益=0.15)),
    ("R3", dict(维度=32, 非线性=0.12, 噪声=0.008, 增益=0.20)),
]


def _w_SNR一档(seed, 维度, 噪声, 增益, 非线性=0.0, 测试数=60):
    bus, wrl, _ = _w_建世界(seed=seed, 维度=维度, 动作维度=维度, 噪声=噪声,
                            增益=增益, 非线性=非线性, 投影维度=维度)
    rng = np.random.default_rng(seed * 19 + 11)
    for _ in range(150):
        bus.探测("world", rng.normal(size=维度), 学习=True)
    信号, 残差 = [], []
    for _ in range(测试数):
        a = rng.normal(size=维度)
        ww = bus.写("world", a, 学习=False).向量
        Ga = wrl.动作影响(a)                    # 世界的真信号（无噪声动作效果）
        信号.append(float(np.sum(np.asarray(Ga, float) ** 2)))
        残差.append(float(np.sum((np.asarray(ww, float) - np.asarray(Ga, float)) ** 2)))
    ς2 = float(np.mean(残差)) / 维度
    return float(np.mean(信号)) / max(ς2 * 维度, 1e-30)


def verify_W7(seed=0) -> dict:
    """W7 SNR 可观测（§6.4）：SNR=E‖Ga‖²/(ς²d) 随世界复杂度（维度/非线性/噪声档）单调上升。"""
    值 = [(名, cfg, _w_SNR一档(seed, **cfg)) for 名, cfg in _W7_档位]
    snrs = [v[2] for v in 值]
    通过 = all(snrs[i] < snrs[i + 1] for i in range(len(snrs) - 1))
    C = [_c("W7 SNR 可观测（随世界复杂度上升）", snrs[-1],
            "SNR 沿复杂度档（维度/非线性/噪声）单调上升", 通过,
            "分档实测 SNR=" + " → ".join(f"{名}(d={cfg['维度']},β={cfg['非线性']},σ={cfg['噪声']})={s:.4g}"
                                        for 名, cfg, s in 值)
            + "。**可失败性**：令噪声随维度同比放大 ⇒ SNR 反降（78.5→18.1→4.1）⇒ 单调不成立 ⇒ FAIL（反例实测）")]
    return _route("W7 SNR 可观测（世界组）", C, "SNR=" + "→".join(f"{s:.4g}" for s in snrs))


W_GROUP = [("W1", verify_W1), ("W2", verify_W2), ("W3", verify_W3),
           ("W4", verify_W4), ("W5", verify_W5), ("W6", verify_W6),
           ("W7", verify_W7)]


# ==================================================================== S 组（R3 · 自我探测循环闭环）
# ★ 独立 S 组（任务书 §5.7/§5.8/§5.10/§6.4 W6；spec `.trae/specs/add-ahi22-self-probe-loop/spec.md`）：
#   与 ALL(P1–P8)、N_GROUP、W_GROUP **分开计分**；判据名/阈值**照抄 Task 0 预注册口径**
#   （meeting8/R3_loop_eval.py，写定于看数据之前），未自创、未放宽（2026-09-26e，见 _CHANGELOG）。
# ★ 闭环层 `ahi_theory/selfprobe.py` 为**纯新增可选模块**：不 import / 不被 import `brain.py`，
#   `mbp.py`/`world.py` 一行未改；**惰性 import**（仅本组被显式调用时才加载）⇒ 既有 P/N/W 路径零变化。
#   零锚点代价实证：meeting8/R3_anchor_zero_cost.txt（锚点 3f753ad00d91285c / f69bdaf723bbaec1 命中、
#   闭环层运行前后 h/m/h_slow/g/F 的 max|Δ|=0）。
# ★ 启用方式（可选启用）：`run_verify.py --self`（纯追加段，默认不打印），或直接调用
#   `verify_S1(seed)…verify_S5(seed)`；默认任何既有验证路径都不加载闭环层。
# ★ 场景（Task 0 预注册，2000 步；**全部随机源 = seed 派生**：总线/循环/设备/世界 ⇒
#   verify_Sx(seed) 逐位可复现，不挑 seed）：t=0 注册 m1,m2(self:线性执行 w=Ma+ξ)、
#   w1(world:随机响应,与 self 同尺度)、world_exo(外生世界源=R2 世界自主时钟 SENSE 增量)、
#   world(R2 世界执行器：RESP=Ga+ξ，W6 口径=我方动作通道，只报告不计分) 并全部标定
#   —— 世界实例注册前**自主预热 200 步**（消除初态 N(0,I) 弛豫瞬态；run1 的 sham随机 S5 AUC≈0.997
#   即该瞬态污染，属场景构造缺陷、已修正并留档 R3_loop_eval_run1_exo_transient.txt，判据一字未动）；
#   t=300 插入 m3(self)；t=600 插入 w3(world)；t=900 拔出 m2 → 挂起；t=1100 插回 → 重归因；
#   t=1400 换装 m3（同 ID、能力不同）→ 重新标定+重新归因（S4 hash 对照）。
_S_维度 = 8
_S_自噪声 = 0.05
_S_世噪声 = 0.02
_S_世增益 = 0.15
_S_步数 = 2000
_S_S5起点 = 200
_S_S5上限 = 400
_S_收敛上限 = 100          # S2 收敛步预注册上界
_S_真值 = {"m1": "self", "m2": "self", "m3": "self",
           "w1": "world", "w2": "world", "w3": "world", "world_exo": "world"}
_S_变体 = {"主": dict(学习=True, 冻结=None, 初始化="恒等"),
           "sham零": dict(学习=False, 冻结=None, 初始化="零"),
           "sham随机": dict(学习=False, 冻结="随机映射", 初始化="恒等")}
_S_CACHE = {}


def _s_场景(seed: int, 变体: str) -> dict:
    """跑一次 Task 0 预注册场景（与 meeting8/R3_loop_eval.py **逐字同口径**），返回 S1–S5 所需读数。

    同 (seed,变体) 结果缓存（纯函数，逐位可复现）；S1–S5 共享同一份场景读数。
    """
    key = (int(seed), str(变体))
    if key in _S_CACHE:
        return _S_CACHE[key]
    from .mbp import MBP总线, MBP模块, 模块描述符, AUC
    from .world import 世界, 世界模块, 世界描述符
    from . import selfprobe as _sp
    cfg = _S_变体[变体]
    D = _S_维度

    class 线性执行模块(MBP模块):
        """self 类真值：线性响应 w = M a + ξ，ξ 很小 ⇒ 可被在线 f 预测（Task 0 场景同款）。"""

        def __init__(self, 描述符, seed=0, 噪声=_S_自噪声):
            super().__init__(描述符)
            d = 描述符.投影维度
            rng = np.random.default_rng(seed)
            self.M = rng.normal(size=(d, d)) / np.sqrt(d)
            self.噪声 = float(噪声)
            self.rng = rng

        def 响应(self, a):
            return self.M @ np.asarray(a, float).ravel() \
                + self.rng.normal(size=self.M.shape[0]) * self.噪声

    class 随机响应模块(MBP模块):
        """world 类真值：响应与指令无关、纯随机；尺度=√(1+自噪声²) 与 self 模块响应**同尺度**。"""

        def __init__(self, 描述符, seed=0, 尺度=None):
            super().__init__(描述符)
            self.rng = np.random.default_rng(seed)
            self.尺度 = float(np.sqrt(1.0 + _S_自噪声 ** 2) if 尺度 is None else 尺度)

        def 响应(self, a):
            return self.rng.normal(size=self.描述符.投影维度) * self.尺度

    def 执行类描述符(mid, 能力):
        return 模块描述符(mid, "执行类", "流式", D, D, "φ_act",
                          采样率="1kHz", 缓冲深度=1, 代谢常数=0.01, 延迟="1ms",
                          能力=tuple(能力), 协议版本="MBP-1.0")

    def 预热(w, n=200):
        """世界自主预热：动作=None 步进 n 步，使初态进入平稳分布（消除弛豫瞬态，run1 修正）。"""
        for _ in range(int(n)):
            w.步(None)
        return w

    bus = MBP总线(投影维度默认_=D, tau=1.0, 心跳超时=3, seed=seed,
                  响应模型初始化=cfg["初始化"])
    loop = _sp.自探测循环(bus, 学习=cfg["学习"], 冻结方式=cfg["冻结"], seed=seed)
    ds = lambda k: seed * 1000 + k          # 设备种子（跨变体一致，seed 派生）
    m1d, m2d = 执行类描述符("m1", ("肩关节",)), 执行类描述符("m2", ("肘关节",))
    w1d = 执行类描述符("w1", ("外部泵",))
    wld = 世界描述符(D, D, "world")
    exd = 世界描述符(D, D, "world_exo")
    loop.插入模块(m1d, 线性执行模块(m1d, seed=ds(1)))
    loop.插入模块(m2d, 线性执行模块(m2d, seed=ds(2)))
    loop.插入模块(w1d, 随机响应模块(w1d, seed=ds(11)))
    loop.插入模块(wld, 世界模块(wld, 预热(世界(维度=D, 动作维度=D, 噪声=_S_世噪声,
                                               增益=_S_世增益, 种子=seed)), seed=seed))
    loop.插入模块(exd, _sp.外生世界模块(exd, 预热(世界(维度=D, 动作维度=D, 噪声=_S_世噪声,
                                                    增益=_S_世增益, 种子=seed + 777))))

    档案 = 图式 = (None, None)
    for t in range(1, _S_步数 + 1):
        if t == 300:
            m3d = 执行类描述符("m3", ("腕关节",))
            loop.插入模块(m3d, 线性执行模块(m3d, seed=ds(3)))
        if t == 600:
            w3d = 执行类描述符("w3", ("外部阀",))
            loop.插入模块(w3d, 随机响应模块(w3d, seed=ds(13)))
        if t == 900:
            loop.拔出模块("m2")
        if t == 1100:
            loop.插回模块("m2")
        if t == 1400:
            换前 = (bus.自我档案哈希(), bus.身体图式哈希())
            m3n = 执行类描述符("m3", ("吸附盘",))          # 同 ID，能力不同
            loop.换装模块("m3", m3n, 线性执行模块(m3n, seed=ds(33)))
            换后 = (bus.自我档案哈希(), bus.身体图式哈希())
            档案, 图式 = (换前[0], 换后[0]), (换前[1], 换后[1])
        loop.步进()

    # ---------------- 收集（与 R3_loop_eval.py 同口径；丢弃事件流大对象，只留读数） ----------------
    归因 = loop.归因表()
    事件 = [dict(t=int(ev_t), mid=mid, label=lab, 步=int(步))
            for (ev_t, mid, lab, 步, _rb, _cf) in loop.迁移日志]
    稳态 = {}
    for mid, ev in loop.证据.items():
        if mid == "world":
            continue
        vals = [x[3] for x in ev.事件流 if x[0] >= 1900]
        稳态[mid] = float(np.mean(vals)) if vals else float("nan")
    正确 = {mid: (归因[mid] == _S_真值[mid]) for mid in 稳态}

    def 抽(mid, 列=3):
        vals = [x[列] for x in loop.证据[mid].事件流 if x[0] >= _S_S5起点]
        return vals[::max(1, len(vals) // _S_S5上限)]

    自侧, 世侧 = 抽("world"), 抽("world_exo")
    rec = dict(seed=int(seed), 变体=变体,
               异常=list(loop.异常隔离),
               完整=loop.完整性(),
               挂起=list(loop.挂起日志),
               插拔=list(loop.插拔日志),
               归因=归因, 事件=事件, 稳态=稳态, 正确=正确,
               档案=档案, 图式=图式,
               S5_auc星=float(AUC(自侧, 世侧)),
               S5_auc_raw=float(AUC(抽("world", 列=4), 抽("world_exo", 列=4))),
               S5_n=(len(自侧), len(世侧)))
    _S_CACHE[key] = rec
    return rec


def _s_事件统计(rec: dict):
    """计分收敛事件（world 执行器不计分）：返回 (收敛步列表, 乱归数)。"""
    步, 错 = [], 0
    for ev in rec["事件"]:
        if ev["mid"] == "world":
            continue
        步.append(ev["步"])
        if ev["label"] != _S_真值.get(ev["mid"], ev["label"]):
            错 += 1
    return 步, 错


def _s_S3统计(rec: dict):
    """稳态（t≥1900）self_t* 按构造真值分桶：返回 (正确率, AUC, n)。"""
    from .mbp import AUC
    自分, 世分 = [], []
    正 = 0
    for mid, ok in rec["正确"].items():
        正 += int(ok)
        (自分 if _S_真值[mid] == "self" else 世分).append(rec["稳态"][mid])
    return 正 / max(len(rec["正确"]), 1), float(AUC(自分, 世分)), len(rec["正确"])


def _s_sham读数(seed: int) -> dict:
    """sham 零/随机两变体的逐 seed 读数（f 冻结、全程学习=False；预注册 sham 门见各判据）。"""
    out = {}
    for 名 in ("sham零", "sham随机"):
        r = _s_场景(seed, 名)
        acc, auc, n = _s_S3统计(r)
        self乱 = sum(1 for mid, tv in _S_真值.items()
                     if tv == "self" and r["归因"].get(mid) == "world")
        out[名] = dict(正确率=acc, auc=auc, n=n, self乱归=self乱, S5_auc=r["S5_auc星"])
    return out


def verify_S1(seed=0) -> dict:
    """S 组 · S1 闭环连续运行（spec S1；场景判据，全部随机源 = seed 派生 ⇒ 逐位可复现）。"""
    r = _s_场景(seed, "主")
    异常 = len(r["异常"])
    完整 = all(v["在线步"] == v["事件"] for v in r["完整"].values())
    挂起齐 = any(e[1] == "m2" for e in r["挂起"])
    重归齐 = any(x[1] == "重归因(插回)" and x[2] == "m2" for x in r["插拔"])
    通过 = (异常 == 0) and 完整 and 挂起齐 and 重归齐
    C = [_c("S1 连续运行（异常隔离=0、事件流完整、挂起/重归因事件齐备）", 异常,
            "= 0 且 事件流完整 且 挂起齐 且 重归因齐", 通过,
            f"2000 步混合场景（插入/拔出/插回/换装/世界扰动）连续运行：异常隔离={异常}；"
            f"事件流完整（逐模块 在线步=事件数）={完整}；挂起事件={r['挂起']}；"
            f"插回重归因={[x for x in r['插拔'] if str(x[1]).startswith('重归因')]}。"
            "可失败性：未捕获异常/断流/漏挂起漏重归因任一发生即 FAIL（见台账）")]
    return _route("S1 连续运行（S 组）", C,
                  f"异常={异常} 完整={完整} 挂起齐={挂起齐} 重归因齐={重归齐}")


def verify_S2(seed=0) -> dict:
    """S 组 · S2 归因收敛（spec S2）：计分收敛步 ≤100 且无乱归（逐 seed）；sham 门照抄预注册（集合层 ≤0.7）。"""
    r = _s_场景(seed, "主")
    步, 错 = _s_事件统计(r)
    sh = _s_sham读数(seed)
    通过 = bool(步) and (max(步) <= _S_收敛上限) and (错 == 0)
    C = [_c("S2 归因收敛（计分收敛步≤100 且 无乱归；sham 乱归）",
            int(max(步)) if 步 else -1,
            f"≤ {_S_收敛上限} 且 乱归=0；sham 门（预注册·集合层）正确率 ≤0.7 且 self 类乱归", 通过,
            f"计分事件 {len(步)} 个（world 执行器按 W6 口径=我方动作通道 ⇒ self，只报告不计分），"
            f"收敛步 中位={float(np.median(步)) if 步 else float('nan'):.0f} 最大={max(步) if 步 else -1}，"
            f"乱归={错}。**sham（f 冻结，逐 seed 读数）**：零 正确率={sh['sham零']['正确率']:.3f}"
            f"/self乱归={sh['sham零']['self乱归']}，随机 正确率={sh['sham随机']['正确率']:.3f}"
            f"/self乱归={sh['sham随机']['self乱归']}（f 冻结 ⇒ self 类归因塌 ⇒ 判据非恒真）；"
            "sham 门=**预注册集合层**口径（Task 0 双集池化正确率 0.500、self乱归率 1.00，"
            "照抄 R3_loop_eval.py shamok，不在 per-seed 层自创加严）")]
    return _route("S2 归因收敛（S 组）", C,
                  f"收敛步最大={max(步) if 步 else -1} 乱归={错}；"
                  f"sham 正确率 {sh['sham零']['正确率']:.2f}/{sh['sham随机']['正确率']:.2f}")


def verify_S3(seed=0) -> dict:
    """S 组 · S3 归属正确率（spec S3）：正确率 ≥0.9 且 self_t* 联合 AUC>0.9（逐 seed）；sham 门照抄预注册（集合层）。"""
    r = _s_场景(seed, "主")
    acc, auc, n = _s_S3统计(r)
    sh = _s_sham读数(seed)
    通过 = (acc >= 0.9) and (auc > 0.9)
    C = [_c("S3 归属正确率 ≥0.9 且 self_t* 联合 AUC>0.9（sham 更低）", float(auc),
            "正确率 ≥ 0.9 且 AUC > 0.9；sham 门（预注册·集合层）正确率 ≤ 0.7", 通过,
            f"正确率={acc:.3f}（{n} 个计分模块按构造真值）；self_t* 联合 AUC={auc:.4f}"
            f"（self 类 vs world 类，按构造真值分桶）。**sham（逐 seed 读数）**：零 正确率="
            f"{sh['sham零']['正确率']:.3f}（self_t* AUC={sh['sham零']['auc']:.3f}）、随机 正确率="
            f"{sh['sham随机']['正确率']:.3f}（AUC={sh['sham随机']['auc']:.3f}）；"
            "sham 门=**预注册集合层**口径（Task 0 双集池化 0.500/0.500，照抄 shamok）。"
            "**诚实边界**：sham 的 self_t* AUC 只被压到 0.66–0.79（ρ 重尾仍留残余可分性），"
            "故预注册 sham 门用**正确率**口径；AUC 只报告不判门")]
    return _route("S3 归属正确率（S 组）", C,
                  f"正确率={acc:.3f} AUC={auc:.4f} n={n}；"
                  f"sham 正确率 {sh['sham零']['正确率']:.2f}/{sh['sham随机']['正确率']:.2f}")


def verify_S4(seed=0) -> dict:
    """S 组 · S4 换身体不换人（spec S4；hash 对照型）：档案 hash 逐位不变、图式 hash 改变、换装重归因正确。"""
    r = _s_场景(seed, "主")
    档案不变 = r["档案"][0] == r["档案"][1]
    图式变 = r["图式"][0] != r["图式"][1]
    重归正确 = any(ev["mid"] == "m3" and ev["t"] > 1400 for ev in r["事件"])
    通过 = 档案不变 and 图式变 and 重归正确
    C = [_c("S4 换身体不换人（档案 hash 逐位不变、图式 hash 改变、换装重归因正确）",
            int(档案不变) + int(图式变) + int(重归正确),
            "3/3（hash 对照）", 通过,
            f"t=1400 同 ID 换能力（腕关节→吸附盘）：自我档案 hash {r['档案'][0]} → {r['档案'][1]}"
            f"（逐位{'相同' if 档案不变 else '改变'}）；身体图式 hash {r['图式'][0]} → {r['图式'][1]}"
            f"（{'改变' if 图式变 else '未变'}）；换装后 m3 重新归因收敛={重归正确}。"
            "Task 0：档案 seed0 1d93f943a1152941 / seed6 2ea8904e64047da4 均逐位不变；图式逐 seed 改变")]
    return _route("S4 换身体不换人（S 组）", C,
                  f"档案 {r['档案'][0]}→{r['档案'][1]}；图式 {r['图式'][0]}→{r['图式'][1]}")


def verify_S5(seed=0) -> dict:
    """S 组 · S5 世界信号融合（spec S5）：我方动作通道 vs 外生世界联合可分 AUC>0.9（逐 seed）；sham 门照抄预注册（集合层）。"""
    r = _s_场景(seed, "主")
    sh = _s_sham读数(seed)
    主 = float(r["S5_auc星"])
    通过 = 主 > 0.9
    C = [_c("S5 世界融合（我方动作通道 vs 外生世界 AUC>0.9；sham ≤0.7 且 差距≥0.3）", 主,
            "AUC > 0.9；sham 门（预注册·集合层）≤0.7 且 差距≥0.3", 通过,
            f"world 执行器（RESP=Ga+ξ，我方 CMD 的可预测响应 ⇒ self 侧）vs 外生世界源"
            f"（自主时钟 Δx=(A−I)x+ξ，与指令无关 ⇒ world 侧）的 self_t* 联合 AUC={主:.4f}"
            f"（t≥{_S_S5起点}，n={r['S5_n']}）；raw self_t(τ=1) 口径 AUC={r['S5_auc_raw']:.4f}；"
            f"sham（逐 seed 读数）零={sh['sham零']['S5_auc']:.4f} 随机={sh['sham随机']['S5_auc']:.4f}。"
            "sham 门=**预注册集合层**口径（Task 0 双集：零 0.5265/0.5407、随机 0.5072/0.6013 ≤0.7，"
            "差距 0.493/0.459 ≥0.3，照抄 shamok）。**诚实边界**：sham S5 AUC 逐 seed 有抖动，"
            "留出集 seed7 的 sham随机=0.7578 单 seed >0.7（集合层均值 0.6013 仍 ≤0.7）"
            "⇒ 门在集合层判定，不在 per-seed 层自创加严。"
            "**run1 诚实记录**：预热修正前 sham随机 AUC≈0.997（R2 世界初态 N(0,I) 弛豫瞬态污染非平稳流，"
            "场景构造缺陷；修正=注册前自主预热 200 步，判据与阈值一字未动；"
            "留档 R3_loop_eval_run1_exo_transient.txt）。Task 0 双集：AUC=1.0000")]
    return _route("S5 世界融合（S 组）", C,
                  f"AUC={主:.4f}（sham {sh['sham零']['S5_auc']:.3f}/{sh['sham随机']['S5_auc']:.3f}，"
                  f"n={r['S5_n']}）")


S_GROUP = [("S1", verify_S1), ("S2", verify_S2), ("S3", verify_S3),
           ("S4", verify_S4), ("S5", verify_S5)]


# ==================================================================== M 组（R4 单模态插件 · 任务书 §5.4/§5.5/§5.9）
# ★ 独立 M 组：与 ALL(P1–P8)、N_GROUP、W_GROUP、S_GROUP **分开计分**；判据名/阈值**照抄 Task 0 预注册**
#   （meeting9/R4_task0_eval.py 文件头，写死于跑任何 M 组数据之前），不得自创/放宽。
#   M3 未单列——spec 的 M1 Scenario「注册与时间特性」已覆盖三种时间特性取数行为（复用 B3 行为），
#   按规格说明并入 M1 计分（本注释与 CRITERIA_AUDIT 均已写明；M_GROUP 只含 M1/M2/M4/M5）。
# ★ **默认不加载模态层**：仅在本组被显式调用时才**惰性 import** `ahi_theory.modality`
#   （沿用 W/S 组惰性 import 模式）⇒ 既有 P1–P8 / N / W / S 判定路径完全不触碰模态层
#   ⇒ 既有输出与计数零变化（锚点逐位不变，见 meeting9/R4_anchor_zero_cost.txt）。
#   模态层不 import / 不被 import brain.py；mbp.py 仅纯追加 `挂投影器()`（既有接口逐位不变）。
# ★ 定稿说明（可选启用）：模态层是**纯新增**的可选模块——默认任何既有验证/运行路径都不会加载它；
#   要启用请**显式**调用本组（`run_verify.py --modality`，或直接调用 `verify_M1(seed)`…），
#   或业务侧显式 注册+挂投影器（见 ahi_theory/modality.py 模块 docstring）。
_M_步数 = 40000          # 预注册（2026-09-26f 修订 16000→40000，评估期整定；见 _CHANGELOG / CRITERIA_AUDIT）
_M_阈值ACC = 0.90        # 照抄 Task 0 预注册
_M_阈值CHANCE带 = 0.40   # 照抄 Task 0 预注册（修订 0.35→0.40 已登记）
_M_阈值GAP = 0.50        # 照抄 Task 0 预注册
_M_单调容差 = 0.03       # 照抄 Task 0 预注册（修订 0.01→0.03 已登记）
_M_检查点步长 = 2000     # 照抄 Task 0 预注册（收敛步计分口径）
_M_CACHE = {}


def _m():
    """惰性取得模态层模块（避免 import verify_all 时就加载模态层）。"""
    from . import modality as _modality_mod
    return _modality_mod


def _m_M2M4读数(seed: int, 步数: int = _M_步数) -> dict:
    """M2/M4 共用的 φ_txt 在线学习读数（同 (seed,步数) 缓存；与 meeting9/R4_task0_eval.py 跑M2M4
    **逐字同口径**：bus seed=7000+seed、设备 seed=seed、φ seed=seed、快照步=[1000]+2000·k、
    评测窗=末 12000 帧、重放丢 256 预热、切换后过渡帧剔除、sham=冻结步 0 参数早/晚两窗取大）。"""
    key = (int(seed), int(步数))
    if key in _M_CACHE:
        return _M_CACHE[key]
    from .mbp import MBP总线
    mo = _m()
    bus = MBP总线(投影维度默认_=512, tau=1.0, 心跳超时=3, seed=7000 + seed)
    dt = mo.文本流描述符("txt_0", "流式", 1)
    dev = mo.文本源模块(dt, seed=seed)
    bus.注册(dt, dev)
    φ = mo.慢特征投影器(mo.N默认, seed=seed)
    bus.挂投影器("txt_0", φ)
    档案前 = bus.自我档案哈希()
    指纹前 = φ.指纹()
    帧, 快照 = mo.在线学文本投影(bus, "txt_0", 步数=步数,
                               快照步=[1000] + list(range(2000, 步数 + 1, _M_检查点步长)))
    y_all = np.array([dev.真值[i] for i in range(1, 步数 + 1)], dtype=int)
    窗0 = 步数 - 12000
    帧窗, y窗 = 帧[窗0:步数], y_all[窗0:步数]
    y评 = y窗[mo.重放预热:]                       # 重放丢预热后行与标签对齐（预热=256）
    排除评 = mo.切换剔除掩码(y窗)[mo.重放预热:]     # 切换后过渡帧剔除（评测侧真值，仅行剔除）
    曲线 = {}
    for T in sorted(快照):
        if T == 0:
            continue
        Z = mo.慢特征投影器.冻结重放(快照[T], φ.α, 帧窗)
        曲线[T] = mo.线性探针准确率(Z, y评, mo.K默认, 排除=排除评)
    Ts = sorted(曲线)
    acc首, acc末 = 曲线[Ts[0]], 曲线[Ts[-1]]
    # sham：φ 冻结于步 0（随机块 + 静默库）——参数冻结 ⇒ 曲线恒定；早/晚两窗各评一次，取大
    Z0晚 = mo.慢特征投影器.冻结重放(快照[0], φ.α, 帧窗)
    sham晚 = mo.线性探针准确率(Z0晚, y评, mo.K默认, 排除=排除评)
    Z0早 = mo.慢特征投影器.冻结重放(快照[0], φ.α, 帧[0:12000])
    sham早 = mo.线性探针准确率(Z0早, y_all[0:12000][mo.重放预热:], mo.K默认,
                              排除=mo.切换剔除掩码(y_all[0:12000])[mo.重放预热:])
    sham = max(sham早, sham晚)
    收敛步 = next((T for T in Ts if 曲线[T] >= _M_阈值ACC), None)
    降幅 = max([0.0] + [曲线[a] - 曲线[b] for a, b in zip(Ts, Ts[1:])])
    φ.已收敛 = 收敛步 is not None
    图式指纹 = bus.身体图式()["txt_0"]["投影器指纹"]
    档案后 = bus.自我档案哈希()
    r = dict(曲线=曲线, Ts=Ts, acc首=acc首, acc末=acc末, sham早=sham早, sham晚=sham晚,
             sham=sham, 收敛步=收敛步, 降幅=降幅, 指纹前=指纹前, 指纹后=φ.指纹(),
             指纹ok=bool((图式指纹 == φ.指纹()) and (φ.指纹() != 指纹前)),
             档案前=档案前, 档案后=档案后, 档案ok=bool(档案后 == 档案前))
    _M_CACHE[key] = r
    return r


def verify_M1(seed=0) -> dict:
    """M 组 · M1 描述符/三正交维度/三种时间特性（spec M1；M3 未单列——三种时间特性取数行为并入本判据）。

    与 meeting9/R4_task0_eval.py 跑M1 **逐字同口径**（bus seed 8000–8002+seed、设备 seed+900/902/903、
    φ seed+901、事件场景 6000 步）。
    """
    mo = _m()
    from .mbp import MBP总线
    # (a) 描述符字段
    bus = MBP总线(投影维度默认_=512, seed=8000 + seed)
    dt = mo.文本流描述符("txt_0", "流式", 1)
    p = bus.注册(dt, mo.文本源模块(dt, seed=seed + 900))
    q = bus.查询("txt_0")
    字段ok = (p.包类型 == "DESC" and p.验证()
              and q.模块类 == "感知类" and q.时间特性 == "流式"
              and q.原始维度 == mo.N默认 and q.投影维度 == 512 and q.投影器 == "φ_txt"
              and q.能力 == ("文本流",) and q.标定状态 == "未标定"
              and q.协议版本 == "MBP-1.0" and bus.已注册() == ("txt_0",))
    # (b) 流式：每步可读、逐步更新（挂状态化 φ_txt）
    φ = mo.慢特征投影器(mo.N默认, seed=seed + 901)
    bus.挂投影器("txt_0", φ)
    包 = []
    for _ in range(30):
        bus.步进(1)
        包.append(bus.读("txt_0"))
    流ok = (all(pp.置信 == 1.0 and pp.验证() and pp.向量.shape == (512,) for pp in 包)
            and all(np.any(包[i].向量 != 包[i + 1].向量) for i in range(29)))
    # (c) 快照：缓冲深度 5，15 读 → 3 帧（B3 行为）
    bus2 = MBP总线(投影维度默认_=512, seed=8001 + seed)
    dk = mo.文本流描述符("snap_0", "快照", 5)
    bus2.注册(dk, mo.文本源模块(dk, seed=seed + 902))
    帧集 = []
    for _ in range(15):
        bus2.步进(1)
        帧集.append(tuple(np.round(bus2.读("snap_0").向量, 12)))
    快照ok = (len(set(帧集)) == 3)
    # (d) 事件：主题切换作事件，非阻塞；事件数 == 内部切换数（真值仅评测）
    bus3 = MBP总线(投影维度默认_=512, seed=8002 + seed)
    de = mo.文本流描述符("evt_0", "事件", 1)
    dev3 = mo.文本源模块(de, seed=seed + 903, 事件模式=True)
    bus3.注册(de, dev3)
    有读 = 空读 = 0
    for _ in range(6000):
        bus3.步进(1)
        pp = bus3.读("evt_0")
        if pp.置信 == 0.0:
            空读 += 1
        else:
            有读 += 1
    切 = len([t for t in dev3.切换步 if 1 <= t <= 6000])
    事件ok = (有读 == 切) and (空读 == 6000 - 有读)
    通过 = bool(字段ok and 流ok and 快照ok and 事件ok)
    C = [_c("M1 描述符字段+三正交维度+三种时间特性（流式/快照/事件；M3 并入）",
            int(字段ok) + int(流ok) + int(快照ok) + int(事件ok), "4/4", 通过,
            f"字段={字段ok}（感知类/流式/64→512/φ_txt/能力=(\"文本流\",)/未标定/MBP-1.0）；"
            f"流式每步可读且逐步更新={流ok}（30 步全 置信=1 且相邻帧不同）；"
            f"快照(缓冲5,15读→3帧)={快照ok}；事件(事件数==内部切换数)={事件ok}"
            f"（{有读} 读 / 切 {切}，空读非阻塞）。可失败性见台账（四项行为测试的结构反例）")]
    return _route("M1 模块描述符与时间特性（M 组）", C,
                  f"字段={字段ok} 流式={流ok} 快照={快照ok} 事件={事件ok}（{有读}读/切{切}）")


def verify_M2(seed=0, 步数=_M_步数) -> dict:
    """M 组 · M2 φ_txt 在线学习（spec M2）：chance→≥0.90 曲线（收敛步计分）、sham=冻结随机 φ、
    φ 指纹入身体图式（R1 口径）、自我档案哈希逐位不变。"""
    r = _m_M2M4读数(seed, 步数)
    通过 = (r["acc首"] <= _M_阈值CHANCE带 and r["降幅"] <= _M_单调容差
            and r["收敛步"] is not None and r["acc末"] >= _M_阈值ACC
            and r["sham"] <= _M_阈值CHANCE带 and r["指纹ok"] and r["档案ok"])
    C = [_c("M2 φ_txt 在线学习（acc首≤0.40、曲线非降≤0.03、收敛步、acc末≥0.90、sham≤0.40、指纹入图式、档案不变）",
            float(r["acc末"]),
            f"acc首≤{_M_阈值CHANCE带} 且 非降(≤{_M_单调容差}) 且 收敛步存在 且 acc末≥{_M_阈值ACC} "
            f"且 sham≤{_M_阈值CHANCE带} 且 指纹入图式 且 档案不变", 通过,
            f"acc首={r['acc首']:.3f}（T=1000，chance=1/K=0.20，带={_M_阈值CHANCE带}）；"
            f"收敛步={r['收敛步']}（首个 acc≥{_M_阈值ACC} 检查点）；acc末={r['acc末']:.3f}；"
            f"最大降幅={r['降幅']:.3f}（容差 {_M_单调容差}，修订已登记）；"
            f"sham（φ 冻结于步 0 随机映射）早={r['sham早']:.3f} 晚={r['sham晚']:.3f} 取大={r['sham']:.3f}"
            f"（≤{_M_阈值CHANCE带}）；φ指纹 {r['指纹前']}→{r['指纹后']}"
            f"（图式指纹=={'一致' if r['指纹ok'] else '**不一致**'}，归身体图式口径、R1 登记）；"
            f"自我档案 {r['档案前']}{'（逐位不变）' if r['档案ok'] else '**已变**'}；"
            f"学习步={步数}（修订 16000→40000 已登记）")]
    return _route("M2 φ_txt 在线学习（M 组）", C,
                  f"acc {r['acc首']:.3f}→{r['acc末']:.3f} 收敛步={r['收敛步']} "
                  f"sham={r['sham']:.3f} 降幅={r['降幅']:.3f}")


def verify_M4(seed=0, 步数=_M_步数) -> dict:
    """M 组 · M4 感知可读性（spec M4）：线性探针 acc末≥0.90、sham≤0.40、gap=acc末−sham≥0.50。"""
    r = _m_M2M4读数(seed, 步数)
    gap = float(r["acc末"]) - float(r["sham"])
    通过 = (r["acc末"] >= _M_阈值ACC and r["sham"] <= _M_阈值CHANCE带 and gap >= _M_阈值GAP)
    C = [_c("M4 线性探针可读性（acc末≥0.90、sham≤0.40、gap≥0.50）", gap,
            f"gap≥{_M_阈值GAP} 且 acc末≥{_M_阈值ACC} 且 sham≤{_M_阈值CHANCE带}", 通过,
            f"acc末={r['acc末']:.3f}（≥{_M_阈值ACC}）；sham={r['sham']:.3f}"
            f"（早 {r['sham早']:.3f} / 晚 {r['sham晚']:.3f}，≤{_M_阈值CHANCE带}）；gap={gap:.3f}"
            f"（≥{_M_阈值GAP}）。探针=Task 0 预注册两阶段分层线性判别（测试块完全留出、"
            "切换后过渡帧剔除对真值/sham 同口径）")]
    return _route("M4 感知可读性（M 组）", C,
                  f"acc末={r['acc末']:.3f} sham={r['sham']:.3f} gap={gap:.3f}")


def _m_M5场景(seed: int, 含文本: bool):
    """M5 场景（与 meeting9/R4_task0_eval.py 跑M5.场景 **逐字同口径**：bus/loop seed=9000+seed、
    模块 seed 9000+seed+1/+2/+3、世界预热 200 步、400 步循环、t=250 拔出 / t=270 插回）。"""
    from .mbp import MBP总线, MBP模块, 模块描述符
    from .world import 世界, 世界模块, 世界描述符
    mo = _m()

    class 线性执行模块(MBP模块):
        def __init__(self, 描述符, seed=0):
            super().__init__(描述符)
            rng = np.random.default_rng(seed)
            d = 描述符.投影维度
            self.M = rng.normal(size=(d, d)) / np.sqrt(d)
            self.rng = rng

        def 响应(self, a):
            return self.M @ np.asarray(a, float).ravel() \
                + self.rng.normal(size=self.描述符.投影维度) * 0.05

        def 标定(self, v):
            return np.zeros(self.描述符.投影维度)

    class 随机响应模块(MBP模块):
        def __init__(self, 描述符, seed=0):
            super().__init__(描述符)
            self.rng = np.random.default_rng(seed)

        def 响应(self, a):
            return self.rng.normal(size=self.描述符.投影维度)

        def 标定(self, v):
            return np.zeros(self.描述符.投影维度)

    bus = MBP总线(投影维度默认_=512, tau=1.0, 心跳超时=3, seed=9000 + seed)
    loop = mo.闭环感知兼容(bus, 学习=True, seed=9000 + seed)
    if 含文本:
        dt = mo.文本流描述符("txt_0", "流式", 1)
        loop.插入模块(dt, mo.文本源模块(dt, seed=seed + 950))
        bus.挂投影器("txt_0", mo.慢特征投影器(mo.N默认, seed=seed + 950))
    d1 = 模块描述符("m1", "执行类", "流式", 8, 8, "φ_act", 能力=("肩",))
    loop.插入模块(d1, 线性执行模块(d1, seed=9000 + seed + 1))
    d2 = 模块描述符("w1", "执行类", "流式", 8, 8, "φ_act", 能力=("泵",))
    loop.插入模块(d2, 随机响应模块(d2, seed=9000 + seed + 2))
    dw = 世界描述符(8, 8, "wld")
    w = 世界(维度=8, 动作维度=8, 噪声=0.02, 增益=0.15, 种子=9000 + seed + 3)
    for _ in range(200):
        w.步(None)
    loop.插入模块(dw, 世界模块(dw, w, seed=9000 + seed + 3))
    for t in range(1, 401):
        if 含文本 and t == 250:
            loop.拔出模块("txt_0")
        if 含文本 and t == 270:
            loop.插回模块("txt_0")
        loop.步进()
    return loop


def verify_M5(seed=0) -> dict:
    """M 组 · M5 闭环兼容（spec M5）：感知类 txt→world 归因正确（R3 口径）、挂起/插回重归因、
    正向对照、与无文本源对照 run 共存互不干扰（迁移日志逐位一致）、异常隔离=0。"""
    A, B = _m_M5场景(seed, True), _m_M5场景(seed, False)
    表A, 表B = A.归因表(), B.归因表()
    never_self = all(row[5] != "self" for row in A.事件流("txt_0")) if "txt_0" in A.证据 else False
    挂起ok = any(mid == "txt_0" for _, mid in A.挂起日志) and \
        any(ev == "重归因(插回)" and mid == "txt_0" for _, ev, mid in A.插拔日志)
    迁A = [e for e in A.迁移日志 if e[1] != "txt_0"]
    共存ok = (迁A == B.迁移日志)
    异常ok = (len(A.异常隔离) == 0 and len(B.异常隔离) == 0)
    # 归因预期（R3 口径）：txt(感知类)→world；m1(线性执行)→self；w1(随机)→world；
    # wld(双向类世界执行器，RESP=Ga+ξ 可预测)→self（self 侧证据，见 selfprobe.py 世界融合口径）
    对 = sum([表A.get("txt_0") == "world", 表A.get("m1") == "self", 表A.get("w1") == "world",
              表A.get("wld") == "self", 表B.get("m1") == "self", 表B.get("w1") == "world",
              表B.get("wld") == "self"])
    归因ok = 对 == 7
    通过 = bool(never_self and 挂起ok and 共存ok and 异常ok and 归因ok)
    C = [_c("M5 闭环兼容（感知类 txt→world 且从未 self、挂起/插回重归因、正向对照、共存逐位、异常隔离=0/0）",
            对, "7/7 归因正确 且 从未self 且 挂起/重归因 且 共存逐位一致 且 异常隔离=0/0", 通过,
            f"归因A={表A} 归因B={表B}（正确 {对}/7；R3 口径：感知类无 CMD 通道 ⇒ world；"
            "世界执行器 RESP=Ga+ξ 为我方 CMD 可预测响应 ⇒ self）；txt 从未 self="
            f"{'✔' if never_self else '✗'}；挂起+插回重归因(txt_0)={'✔' if 挂起ok else '✗'}"
            f"（挂起 {len(A.挂起日志)} 条）；与无文本源对照 run 迁移日志逐位一致="
            f"{'✔' if 共存ok else '✗'}（感知分支不消耗指令流）；异常隔离 A/B={len(A.异常隔离)}/"
            f"{len(B.异常隔离)}。归因正确率的 sham 对照继承自 R3 S2/S3（惰性 f ⇒ 0.500），见台账")]
    return _route("M5 闭环兼容（M 组）", C,
                  f"归因A={表A}；从未self={never_self} 共存逐位={共存ok} 异常={len(A.异常隔离)}/{len(B.异常隔离)}")


M_GROUP = [("M1", verify_M1), ("M2", verify_M2), ("M4", verify_M4), ("M5", verify_M5)]


# ==================================================================== I 组（INT 系统接入与整合 · 2026-09-26g）
# ★ 独立 I 组：与 ALL(P1–P8)、N_GROUP、W_GROUP、S_GROUP、M_GROUP **分开计分**；
#   判据口径**照抄 spec `add-ahi22-integration`**（I1 连续运行 / I2 内核零扰动 / I3 集成复测对照 /
#   I4 端到端叙事），未自创、未放宽；P/N/W/S/M 判据一字未改。
# ★ 装配器 `ahi_theory/system.py` 为**纯新增**（不改内核；惰性 import——仅本组被显式调用时加载，
#   沿用 W/S/M 组模式 ⇒ 既有 P/N/W/S/M 判定路径零变化）。
# ★ I3 为**对照判据**（cls D）：测量 = meeting10/INT_i3_groups_assembled.json 的四组 ×6 seed
#   「单独模式 vs 集成环境」逐位对照记录（探针生成）；证据文件缺失 ⇒ 诚实 FAIL。
_I1_步数 = 5000          # spec I1：≥5000
_I4_步数 = 2000          # spec I4 场景长度（覆盖六拍；I1 另以 5000 步计）


def _i1场景(seed: int):
    """I1 混合场景（与 meeting10/INT_i1_poweron_5000.py 同形；wld d=16 = P1 修复的装配内实证）。"""
    from .system import AHI系统
    sys_ = AHI系统(dict(seed=100 + int(seed), 世界维度=16, 非我对照=True))
    for t in range(1, _I1_步数 + 1):
        if t == 400:
            sys_.插入执行模块("m2", ("肘关节",))
        elif t == 900:
            sys_.拔出模块("m2")
        elif t == 1100:
            sys_.插回模块("m2")
        elif t == 1600:
            sys_.换装执行模块("m2", ("吸附盘",))
        elif t == 2400:
            sys_.插入执行模块("m3", ("腕关节",))
        elif t == 2800:
            sys_.拔出模块("m3")
        elif t == 3000:
            sys_.插回模块("m3")
        sys_.步进()
    末 = sys_.关闭()
    return sys_, 末


def verify_I1(seed=0) -> dict:
    """I 组 · I1 系统装配与连续运行（spec I1）：装配后混合场景 ≥5000 步无未捕获异常、状态汇总五段齐。"""
    sys_, 末 = _i1场景(seed)
    异常 = len(sys_.闭环.异常隔离)
    完整 = all(v["在线步"] == v["事件"] for v in sys_.闭环.完整性().values())
    五段 = all(k in 末 for k in ("内核", "总线模块表", "归因", "世界", "模态"))
    归因 = 末["归因"]["归因表"]
    预期 = {"m1": "self", "m2": "self", "m3": "self", "wm1": "world",
            "txt_0": "world", "wld": "self", "evt_0": "unknown"}
    归因齐 = all(归因.get(k) == v for k, v in 预期.items())
    时钟齐 = (末["内核"]["t"] == _I1_步数 and 末["运行"]["时钟bus"] == _I1_步数
              and 末["世界"]["t"] == 200 + _I1_步数)
    通过 = (异常 == 0) and 完整 and 五段 and 归因齐 and 时钟齐 and (末["归因"]["复核触发数"] == 0)
    C = [_c("I1 系统装配与连续运行（异常隔离=0、事件流完整、状态汇总五段齐、归因符合口径、时钟齐）",
            异常, "= 0 且 完整 且 五段齐 且 归因齐 且 时钟齐 且 复核触发=0", 通过,
            f"{_I1_步数} 步混合场景（插入/拔出/插回/换装 ×2 轮、世界 d=16 持续演化、模态流、"
            f"闭环归因全程）：异常隔离={异常}；完整性={完整}；状态汇总五段齐={五段}；归因={归因}"
            f"（wld d=16→self = P1 修复后覆盖域扩展的装配内实证；evt_0→unknown = P2 口径内行为）；"
            f"时钟 bus/brain/world={末['运行']['时钟bus']}/{末['内核']['t']}/{末['世界']['t']}"
            f"（world=200 预热+{_I1_步数} 探测）；复核触发={末['归因']['复核触发数']}。"
            "可失败性：未捕获异常/断流/汇总缺段/归因漂移/时钟错位任一发生即 FAIL（台账见 "
            "CRITERIA_AUDIT；探针证据 meeting10/INT_i1_poweron_5000.txt ×3 run）")]
    return _route("I1 系统装配与连续运行（I 组）", C,
                  f"异常={异常} 完整={完整} 五段齐={五段} 归因齐={归因齐} 时钟齐={时钟齐}")


def verify_I2(seed=0) -> dict:
    """I 组 · I2 内核零扰动（spec I2）：装配后 M6 口径哈希逐位不变（锚点 seed0/1）且同输入流 max|Δ|=0。"""
    import hashlib
    from .system import AHI系统

    def 轨迹(sd):
        b = Brain(seed=sd, intero=False)
        return b.run(1500, seed=sd + 1)

    def 哈希(tr):
        blob = np.concatenate([tr["h"].ravel(), tr["m"].ravel(), tr["g"].ravel(),
                               tr["h_slow"].ravel(), tr["F"]])
        return hashlib.sha256(blob.tobytes()).hexdigest()[:16]

    锚点表 = {0: "3f753ad00d91285c", 1: "f69bdaf723bbaec1"}   # post-R0C（meeting3/M6_state_hash.py）
    前 = 轨迹(seed)
    sys_ = AHI系统(dict(seed=700 + int(seed), 世界维度=16))
    for _ in range(300):
        sys_.步进()
    末 = sys_.关闭()
    后 = 轨迹(seed)
    md = max(float(np.max(np.abs(后[k] - 前[k]))) for k in ("h", "m", "h_slow", "g", "F"))
    哈希一致 = 哈希(后) == 哈希(前)
    有锚 = seed in 锚点表
    锚命中 = (哈希(后) == 锚点表[seed]) if 有锚 else True
    通过 = 哈希一致 and (md == 0.0) and 锚命中
    C = [_c("I2 内核零扰动（装配后 M6 哈希逐位不变 且 同输入流 max|Δ|=0）", md,
            "= 0（有锚点 seed 另要求命中 post-R0C 表）", 通过,
            f"装配前哈希={哈希(前)} 装配后哈希={哈希(后)}（{'逐位一致' if 哈希一致 else '**改变**'}）；"
            f"max|Δ|(h/m/h_slow/g/F)={md:.3g}；seed{seed}"
            f"{'命中 post-R0C 锚点=' + str(锚命中) + '（' + 锚点表[seed] + '）' if 有锚 else '不在锚点表（仅做装配前后逐位对照，如实登记）'}；"
            "同输入流=Brain 自带种子化内部驱动的同参 Brain.run(1500, seed=seed+1)；"
            "装配器（AHI系统 seed=700+seed、世界 d=16）运行 300 拍后再重跑同参轨迹。"
            "**删除实验（Nec=1）**：拆掉全部装配层 ⇒ 逐位回到纯内核（见台账）")]
    return _route("I2 内核零扰动（I 组）", C,
                  f"哈希一致={哈希一致} max|Δ|={md:.3g} 锚命中={锚命中}（有锚={有锚}）")


def verify_I3(seed=0) -> dict:
    """I 组 · I3 集成复测（对照判据 cls D）：集成环境复跑 N/W/S/M 与单独模式逐位对照（证据=探针 JSON）。"""
    import json as _json
    import os as _os
    路径 = _os.path.join(_os.path.dirname(_os.path.dirname(_os.path.abspath(__file__))),
                         "meeting10", "INT_i3_groups_assembled.json")
    if not _os.path.exists(路径):
        C = [_c("I3 集成复测对照（N/W/S/M 集成 vs 单独 逐位一致）", -1, "对照差异数 = 0", False,
                "证据文件缺失（meeting10/INT_i3_groups_assembled.json 不存在）⇒ 诚实 FAIL。"
                "本判据为对照型（cls D）：由探针 meeting10/INT_i3_groups_assembled.py 先跑单独模式、"
                "清缓存、装配 300 拍、再跑集成模式、逐判据逐 seed diff 后落盘，本函数只复核其结论；"
                "不新造阈值、不静默通过")]
        return _route("I3 集成复测对照（I 组）", C, "证据文件缺失")
    rec = _json.load(open(路径, encoding="utf-8"))
    差异条数 = int(rec.get("差异条数", -1))
    差异归因 = rec.get("差异归因", [])
    通过 = bool(rec.get("通过", False)) and 差异条数 == 0
    C = [_c("I3 集成复测对照（N/W/S/M 集成 vs 单独 逐位一致）", 差异条数, "= 0（差异须逐条登记归因）", 通过,
            f"四组（N/W/S/M）× 6 seed 在装配环境（AHI系统 装配+300 拍后同进程）复跑，与各自单独模式"
            f"读数逐位对照：差异条数={差异条数}（{('；'.join(差异归因)) if 差异归因 else '无'}）；"
            "W 组判据本体零改动；'非我'对照位按上轮建议作为装配器注册表成员（wm1）落地=追加而非改动。"
            "证据 meeting10/INT_i3_groups_assembled.txt/.json")]
    return _route("I3 集成复测对照（I 组）", C, f"差异条数={差异条数} 通过={通过}")


def _i4场景(seed: int):
    """I4 叙事场景（与 meeting10/INT_i4_narrative.py 同形；含 B4 无脉冲对照 run）。"""
    from .system import AHI系统
    sys_ = AHI系统(dict(seed=300 + int(seed), 世界维度=16, 非我对照=True))
    φ前 = sys_.φtxt.指纹()
    档案 = None
    F迹 = []
    u脉冲 = np.random.default_rng(555).normal(size=24) * 0.05
    异常 = []
    for t in range(1, _I4_步数 + 1):
        try:
            if t == 700:
                档案 = (sys_.bus.自我档案哈希(), sys_.bus.身体图式哈希())
                sys_.换装执行模块("m2", ("吸附盘",))
                档案 = 档案 + (sys_.bus.自我档案哈希(), sys_.bus.身体图式哈希())
            elif t == 1500:
                sys_.插入执行模块("m3", ("腕关节",))
            elif t == 1700:
                sys_.拔出模块("m3")
            elif t == 1900:
                sys_.插回模块("m3")
            if 1000 <= t < 1040:
                sys_.步进(u_ext=u脉冲)
            else:
                sys_.步进()
            if 995 <= t <= 1045:
                F迹.append((t, float(sys_.brain.F)))
        except Exception as exc:              # noqa: BLE001 —— 场景判据：异常即证据
            异常.append("%s@%d: %s" % (type(exc).__name__, t, exc))
            break
    # B4 删除实验对照：同 seed、同拍数、去掉 u_ext 注入
    对照 = AHI系统(dict(seed=300 + int(seed), 世界维度=16, 非我对照=True))
    对照F = {}
    for t in range(1, 1041):
        对照.步进()
        if 1000 <= t < 1040:
            对照F[t] = float(对照.brain.F)
    F脉冲 = {t_: f for (t_, f) in F迹 if 1000 <= t_ < 1040}
    mdF = max((abs(F脉冲[t] - 对照F[t]) for t in F脉冲 if t in 对照F), default=0.0)
    末 = sys_.关闭()
    return dict(φ前=φ前, 档案=档案, F迹=F迹, mdF=mdF, 异常=异常, 末=末, sys_=sys_)


def verify_I4(seed=0) -> dict:
    """I 组 · I4 端到端叙事（spec I4）：连续场景六拍（探测→归因→档案持久→世界扰动→模态流入→插拔重归因）有据。"""
    r = _i4场景(seed)
    sys_, 末, 异常 = r["sys_"], r["末"], r["异常"]
    迁移 = sys_.闭环.迁移日志
    归因 = 末["归因"]["归因表"]
    B2ok = (any(e[1] == "wld" and e[2] == "self" for e in 迁移)
            and any(e[1] == "m1" and e[2] == "self" for e in 迁移)
            and any(e[1] == "wm1" and e[2] == "world" for e in 迁移)
            and any(e[1] == "txt_0" and e[2] == "world" for e in 迁移))
    B3ok = r["档案"][0] == r["档案"][2] and r["档案"][1] != r["档案"][3]
    B4ok = (r["mdF"] > 0.0) and (归因.get("wld") == "self")
    B5ok = (sys_.φtxt.指纹() != r["φ前"]) and (sys_.φtxt.n重构 >= 1) and (归因.get("txt_0") == "world")
    B6ok = (sum(1 for e in 迁移 if e[1] == "m3") >= 2
            and any(mid == "m3" and tt >= 1700 for tt, mid in sys_.闭环.挂起日志)
            and 归因.get("m3") == "self")
    五段齐 = all(k in 末 for k in ("内核", "总线模块表", "归因", "世界", "模态"))
    完整ok = all(v["在线步"] == v["事件"] for v in sys_.闭环.完整性().values())
    B7ok = 五段齐 and 完整ok and len(异常) == 0
    拍数 = sum(1 for ok in (B2ok, B3ok, B4ok, B5ok, B6ok, B7ok) if ok)
    通过 = (拍数 == 6)
    C = [_c("I4 端到端叙事（装配器驱动的连续场景六拍有据）", 拍数, "6/6 拍有据（含 B4 无脉冲对照）", 通过,
            f"连续 {_I4_步数} 步：B2 探测→归因（wld d=16→self、m1→self、wm1→world、txt_0→world）={B2ok}；"
            f"B3 档案持久（自我档案 {r['档案'][0][:8]}…→{r['档案'][2][:8]}… 逐位{'不变' if r['档案'][0] == r['档案'][2] else '改变'}、"
            f"身体图式{'改变' if r['档案'][1] != r['档案'][3] else '未变'}）={B3ok}；"
            f"B4 世界扰动（u_ext 注入 40 拍 vs 无脉冲对照 run 的 F 轨迹 max|ΔF|={r['mdF']:.3g}>0 ⇒ 注入到达内核；"
            f"wld 归因保持 self）={B4ok}；B5 模态流入（φ_txt 指纹改变={sys_.φtxt.指纹() != r['φ前']}、"
            f"n重构={sys_.φtxt.n重构}）={B5ok}；B6 插拔重归因（m3 插入@1500/挂起/插回重归因）={B6ok}；"
            f"B7 末态（五段齐={五段齐} 完整性={完整ok} 异常={len(异常)}）={B7ok}。"
            "可失败性：任一拍证据缺失即 FAIL；B4 为删除实验（去掉注入 ⇒ F 轨迹逐位相同 ⇒ 该拍 FAIL）")]
    return _route("I4 端到端叙事（I 组）", C, f"六拍 {拍数}/6 有据 max|ΔF|={r['mdF']:.3g} 异常={len(异常)}")


I_GROUP = [("I1", verify_I1), ("I2", verify_I2), ("I3", verify_I3), ("I4", verify_I4)]


# ════════════════════════════════════════════════════════════════════════
# K 组（V2 无标度判据；M1 K-BATTERY 仪器自证；2026-09-28 注册收口，纯追加）
#   K5 = 元判据（尺子先于对象）：在合成已知真值上自证仪器可分辨，是 K1–K4 的前置门。
#   K1–K4 的仪器接口已在 k_battery.py（k1_regime_ok/k2_dwell/k3_two_stage/k4_verdict），
#   其引擎侧测量待 V2 六层引擎（M5/M7 供给 k*(t)/e_c/α 序列）后另行预注册接入——本轮不虚设。
# ════════════════════════════════════════════════════════════════════════
_K5_T = 131072                     # 规格窗（k5_run docstring：64K 窗过短，D 交叉不可见）
_K5_B = 40                         # B=40/情形（定稿 §3.1 K5 行）
_K5_JUDGE = list(range(0, 6))      # 判据集（master seed 块）
_K5_HOLDOUT = list(range(6, 12))   # 留出集（未参与一切调参）
_K5_NAME = "K5 仪器自证（六情形合成 + 打洞族 G；双集×五门）"
_K5_CACHE = {}


def verify_K5(seed=0) -> dict:
    """K 组 · K5 仪器自证（种子块级元判据，2026-09-28 注册收口）。

    seed 参数**不进入测量**：K5 的判定单位是 master 种子块而非单 seed（组驱动 SEEDS
    循环传参仅为签名兼容）——双集两块固定 judge=[0..5] / holdout=[6..11]，首次计算后
    进程内缓存（_K5_CACHE，与 _S_CACHE/_M_CACHE 同律），同进程重复调用零开销。
    五门由 k5_gate 原样给出（本函数不复制阈值）：synth≥0.90 ∧ G1@5%≥0.90 ∧
    G1@20%≥0.90 ∧ G2≥0.90 ∧ G3≥0.85；两块全部过线才 passed。
    dev 第三分区（100–107）不重复跑：云机 #56 已验（meeting12/M1_k5_threeway_r55.out）、
    本机复现 M1_k5_threeway_本机.out，落盘为证。
    """
    if "res" not in _K5_CACHE:
        import time                              # 函数内导入：模块头部保持原样（追加纪律）
        from ahi_theory import k_battery as _kb   # 惰性导入：默认全量判据路径不加载仪器
        _blocks = {}
        for _bn, _seeds in (("judge", _K5_JUDGE), ("holdout", _K5_HOLDOUT)):
            _t0 = time.time()
            _r = _kb.k5_run(_seeds, B=_K5_B, T=_K5_T)
            _g = _kb.k5_gate(_r)
            _blocks[_bn] = dict(run=_r, gate=_g, secs=time.time() - _t0)
        _K5_CACHE["res"] = _blocks
    _blocks = _K5_CACHE["res"]
    _allpass = all(_b["gate"]["passed"] for _b in _blocks.values())
    _synth_min = min(_b["run"]["synth"]["overall"] for _b in _blocks.values())
    C = [_c(_K5_NAME, _synth_min,
            "双集五门全过（synth≥0.90、G1@5%≥0.90、G1@20%≥0.90、G2≥0.90、G3≥0.85）",
            _allpass,
            "; ".join("%s(B=%d,T=%d,%.0fs) synth=%.4f G={%s} gate=%s" % (
                _bn, _b["run"]["B"], _b["run"]["T"], _b["secs"],
                _b["run"]["synth"]["overall"],
                ", ".join("%s=%.3f" % (_k, _v) for _k, _v in _b["gate"]["G"].items()),
                _b["gate"]["passed"]) for _bn, _b in _blocks.items())
            + "。**种子块级判据**（master 0–5/6–11；seed 传参不进入测量）；"
              "as-is 历史失败（双集 0.610/0.663 全门 FAIL）原样留档 meeting12/M1_k5_selftest.txt；"
              "dev 第三分区只读复测见 meeting12/M1_k5_threeway_r55.out（云机 #56）与 "
              "M1_k5_threeway_本机.out（本机）。")]
    return _route("K5 仪器自证（K 组）", C,
                  "双集五门 %s；synth min=%.4f（B=%d、T=%d/块）"
                  % ("全过" if _allpass else "未全过", _synth_min, _K5_B, _K5_T))


K_GROUP = [("K5", verify_K5)]
